// BGM MIX STUDIO v16 (単体HTML)。会員限定ルートからのみ配信する。public/ には置かないこと。
export const BGM_MIX_STUDIO_HTML: string = "<!DOCTYPE html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>BGM MIX STUDIO v16 CLEAN — Casa Shindy</title>\n<style>\n  :root{\n    --bg:#0b0b0d; --panel:#141417; --panel2:#1a1a1f; --line:#2a2a31;\n    --text:#e8e6e1; --dim:#9a97a3; --gold:#d4a548; --teal:#4fd1c5;\n    --red:#e0605c; --lane:#101013;\n  }\n  *{box-sizing:border-box; margin:0; padding:0;}\n  html,body{height:100%;}\n  body{background:var(--bg); color:var(--text); font-family:\"Hiragino Kaku Gothic ProN\",\"Hiragino Sans\",\"Noto Sans JP\",system-ui,sans-serif; font-size:13px; overflow:hidden;}\n  button{font:inherit; color:inherit;}\n  input,select{font:inherit;}\n  .hidden{display:none !important;}\n\n  #app{display:flex; flex-direction:column; height:100vh;}\n\n  /* ===== top bar ===== */\n  .topbar{display:flex; align-items:center; gap:14px; flex-wrap:wrap; padding:8px 12px; background:var(--panel); border-bottom:1px solid var(--line);}\n  .brand{display:flex; flex-direction:column; line-height:1.15; margin-right:2px;}\n  .brand-mark{font-size:10px; letter-spacing:.28em; color:var(--gold); font-weight:700;}\n  .brand-name{font-size:17px; font-weight:800; letter-spacing:.06em;}\n  .version-badge{font-size:10px; color:#0b0b0d; background:var(--teal); border-radius:3px; padding:1px 6px; font-weight:700; vertical-align:middle; margin-left:6px; letter-spacing:.08em;}\n  .toolbar-group{display:flex; align-items:center; gap:6px;}\n  .toolbar-sep{width:1px; height:26px; background:var(--line);}\n  .btn{background:var(--panel2); border:1px solid var(--line); border-radius:6px; padding:6px 10px; cursor:pointer; white-space:nowrap;}\n  .btn:hover{border-color:var(--gold); color:#fff;}\n  .btn:disabled{opacity:.45; cursor:default;}\n  .btn:disabled:hover{border-color:var(--line); color:inherit;}\n  .btn-primary{background:#3a2f16; border-color:var(--gold); color:#f3d492; font-weight:700;}\n  .btn-export{background:#123a36; border-color:var(--teal); color:#a9efe8; font-weight:700;}\n  .btn-small{padding:3px 9px;}\n  .btn-transport{font-size:15px; min-width:40px; text-align:center;}\n  .time-display{font-variant-numeric:tabular-nums; font-size:14px; min-width:128px; text-align:center; color:#f3d492;}\n  .snap-toggle{color:var(--dim); display:flex; align-items:center; gap:4px; cursor:pointer; white-space:nowrap;}\n  .ctl-label{color:var(--dim); font-size:11px; white-space:nowrap;}\n  select.ctl, input.ctl-num{background:var(--panel2); color:var(--text); border:1px solid var(--line); border-radius:5px; padding:5px 6px;}\n  input.ctl-num{width:52px; text-align:right; font-variant-numeric:tabular-nums;}\n  .meter-group{gap:8px;}\n  .meter-label{font-size:10px; letter-spacing:.18em; color:var(--dim);}\n  .meter-bars{display:flex; flex-direction:column; gap:3px; width:110px;}\n  .meter-track{height:7px; background:#060607; border:1px solid var(--line); border-radius:3px; overflow:hidden;}\n  .meter-fill{height:100%; width:0%; background:linear-gradient(to right,#3fae6a,#9ecb4f 55%,#e8c832 78%,#d33 95%); transition:width .05s linear;}\n  .meter-clip-indicator{background:var(--panel2); border:1px solid var(--line); border-radius:4px; padding:3px 7px; font-size:10px; letter-spacing:.1em; color:var(--dim); cursor:pointer;}\n  .meter-clip-indicator.active{background:#7c1d1d; border-color:var(--red); color:#ffd7d5;}\n\n  /* ===== workspace ===== */\n  .workspace{flex:1; display:flex; min-height:0;}\n  .track-headers{width:272px; flex:0 0 272px; background:var(--panel); border-right:1px solid var(--line); overflow-y:hidden; overflow-x:hidden;}\n  .ruler-spacer{height:28px; border-bottom:1px solid var(--line); display:flex; align-items:center; padding:0 10px; color:var(--dim); font-size:11px;}\n  .track-header{height:96px; border-bottom:1px solid var(--line); padding:7px 9px; display:flex; flex-direction:column; gap:5px; cursor:pointer;}\n  .track-header.selected{background:#1e1c15; box-shadow:inset 3px 0 0 var(--gold);}\n  .th-top{display:flex; align-items:center; gap:6px;}\n  .th-color{width:10px; height:10px; border-radius:50%; flex:0 0 10px;}\n  .th-name{font-weight:700; font-size:12.5px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; flex:1;}\n  .th-icon-btn{background:transparent; border:1px solid transparent; border-radius:4px; color:var(--dim); cursor:pointer; padding:1px 5px; font-size:12px;}\n  .th-icon-btn:hover{color:#fff; border-color:var(--line);}\n  .th-row{display:flex; align-items:center; gap:6px;}\n  .th-row label{color:var(--dim); font-size:10.5px; width:26px; flex:0 0 26px;}\n  .th-row input[type=range]{flex:1; accent-color:var(--gold); height:14px;}\n  .th-row .th-val{font-size:10.5px; color:var(--dim); width:52px; flex:0 0 52px; text-align:right; font-variant-numeric:tabular-nums;}\n  .th-btns{display:flex; gap:4px; align-items:center;}\n  .th-btn{min-width:26px; padding:2px 6px; background:var(--panel2); border:1px solid var(--line); border-radius:4px; cursor:pointer; font-size:11px; text-align:center;}\n  .th-btn.active-m{background:#7c5a12; border-color:var(--gold); color:#ffe1a1;}\n  .th-btn.active-s{background:#14524c; border-color:var(--teal); color:#a9efe8;}\n  .th-btn.active-fx{background:#33334a; border-color:#8f8fd0; color:#d5d5ff;}\n  .th-bpm{font-size:10.5px; color:var(--teal); margin-left:auto; font-variant-numeric:tabular-nums;}\n\n  .timeline-scroll{flex:1; overflow:auto; position:relative; background:var(--lane);}\n  .timeline-inner{position:relative; min-height:100%;}\n  .ruler{height:28px; position:sticky; top:0; z-index:6; background:#17171b; border-bottom:1px solid var(--line); cursor:pointer;}\n  .ruler-tick{position:absolute; top:0; height:100%; border-left:1px solid #26262d; color:var(--dim); font-size:10px; padding:3px 0 0 4px; pointer-events:none; font-variant-numeric:tabular-nums;}\n  .tracks-container{position:relative;}\n  .track-lane{height:96px; border-bottom:1px solid #1d1d22; position:relative; background-image:linear-gradient(to right, rgba(255,255,255,.028) 1px, transparent 1px); background-size:40px 100%;}\n  .track-lane.drop-hint{box-shadow:inset 0 0 0 2px var(--teal);}\n  .playhead{position:absolute; top:0; bottom:0; width:2px; background:var(--red); z-index:7; pointer-events:none; box-shadow:0 0 6px rgba(224,96,92,.7);}\n  .playhead::before{content:\"\"; position:absolute; top:0; left:-5px; border:6px solid transparent; border-top:8px solid var(--red);}\n\n  .clip{position:absolute; top:8px; height:80px; border-radius:6px; overflow:hidden; cursor:grab; border:1px solid rgba(255,255,255,.22); background:#22222a;}\n  .clip.selected{border-color:#fff; box-shadow:0 0 0 2px var(--gold), 0 4px 14px rgba(0,0,0,.5); z-index:4;}\n  .clip canvas{position:absolute; inset:0; width:100%; height:100%;}\n  .clip-label{position:absolute; top:2px; left:22px; right:22px; font-size:11px; font-weight:700; color:#fff; text-shadow:0 1px 3px rgba(0,0,0,.9); overflow:hidden; text-overflow:ellipsis; white-space:nowrap; pointer-events:none; z-index:3;}\n  .clip-bpm{position:absolute; bottom:3px; left:6px; font-size:10px; color:#ffe1a1; background:rgba(0,0,0,.55); border-radius:3px; padding:0 5px; pointer-events:none; z-index:3; font-variant-numeric:tabular-nums;}\n  .clip-xfade-badge{position:absolute; bottom:3px; right:6px; font-size:10px; color:#a9efe8; background:rgba(0,0,0,.55); border-radius:3px; padding:0 5px; pointer-events:none; z-index:3;}\n  .trim-handle{position:absolute; top:0; bottom:0; width:9px; z-index:5; cursor:ew-resize; background:rgba(255,255,255,.10);}\n  .trim-handle.left{left:0; border-right:1px solid rgba(255,255,255,.25);}\n  .trim-handle.right{right:0; border-left:1px solid rgba(255,255,255,.25);}\n  .trim-handle:hover{background:rgba(212,165,72,.5);}\n  .more-mark{position:absolute; top:34px; font-size:13px; color:rgba(255,255,255,.75); z-index:3; pointer-events:none; text-shadow:0 1px 2px #000;}\n  .more-mark.left{left:11px;} .more-mark.right{right:11px;}\n  .fade-handle{position:absolute; top:3px; width:11px; height:11px; border-radius:50%; background:#fff; border:2px solid rgba(0,0,0,.55); z-index:6; cursor:ew-resize; box-shadow:0 1px 3px rgba(0,0,0,.6);}\n  .fade-handle.in{left:12px;} .fade-handle.out{right:12px;}\n  .fade-shade{position:absolute; top:0; bottom:0; z-index:2; pointer-events:none; background:rgba(0,0,0,.48);}\n  .fade-shade.in{left:0; clip-path:polygon(0 0, 100% 0, 0 100%);}\n  .fade-shade.out{right:0; clip-path:polygon(0 0, 100% 0, 100% 100%);}\n\n  /* ===== inspector ===== */\n  #inspector{background:var(--panel); border-top:1px solid var(--line); max-height:248px; overflow-y:auto; padding:8px 12px 10px;}\n  .insp-head{display:flex; align-items:center; gap:10px; margin-bottom:6px;}\n  .insp-title{font-weight:800; letter-spacing:.04em;}\n  .insp-title .accent{color:var(--gold);}\n  .insp-close{margin-left:auto;}\n  .insp-body{display:flex; gap:18px; flex-wrap:wrap;}\n  .insp-section{min-width:230px; flex:1; max-width:420px; background:var(--panel2); border:1px solid var(--line); border-radius:8px; padding:8px 10px;}\n  .insp-section h4{font-size:11px; letter-spacing:.14em; color:var(--dim); margin-bottom:6px; display:flex; align-items:center; gap:8px;}\n  .insp-section h4 label{display:flex; align-items:center; gap:4px; color:var(--text); letter-spacing:0; font-size:12px; cursor:pointer;}\n  .fx-row{display:flex; align-items:center; gap:7px; margin:4px 0;}\n  .fx-row > span:first-child{width:86px; flex:0 0 86px; color:var(--dim); font-size:11.5px;}\n  .fx-row input[type=range]{flex:1; accent-color:var(--gold);}\n  .fx-row .fx-val{width:64px; flex:0 0 64px; text-align:right; font-size:11.5px; color:var(--dim); font-variant-numeric:tabular-nums;}\n  .fx-row input[type=number]{width:74px; background:var(--bg); color:var(--text); border:1px solid var(--line); border-radius:4px; padding:3px 5px; text-align:right;}\n  .fx-row select{background:var(--bg); color:var(--text); border:1px solid var(--line); border-radius:4px; padding:3px 4px;}\n  .preset-btn{background:var(--bg); border:1px solid var(--line); border-radius:4px; padding:2px 7px; cursor:pointer; font-size:11px;}\n  .preset-btn:hover{border-color:var(--teal); color:#a9efe8;}\n  .insp-note{color:var(--dim); font-size:11px; line-height:1.5;}\n\n  /* ===== status bar / menu ===== */\n  .statusbar{display:flex; align-items:center; gap:12px; padding:6px 12px; background:var(--panel); border-top:1px solid var(--line); color:var(--dim);}\n  #statusText{flex:1; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}\n  .context-menu{position:fixed; z-index:50; background:#202027; border:1px solid var(--line); border-radius:8px; padding:4px; min-width:220px; box-shadow:0 10px 30px rgba(0,0,0,.6);}\n  .context-menu-item{padding:6px 10px; border-radius:5px; cursor:pointer; white-space:nowrap;}\n  .context-menu-item:hover{background:#33333f; color:#fff;}\n  .context-menu-item.danger:hover{background:#5a2323;}\n  .context-menu-sep{height:1px; background:var(--line); margin:4px 6px;}\n  #dropOverlay{position:fixed; inset:0; z-index:80; background:rgba(10,20,18,.82); border:3px dashed var(--teal); display:flex; align-items:center; justify-content:center; font-size:22px; font-weight:800; color:#a9efe8; pointer-events:none;}\n  progress#busyProgress{width:180px; accent-color:var(--gold);}\n</style>\n</head>\n<body>\n<div id=\"app\">\n\n  <header class=\"topbar\">\n    <div class=\"brand\">\n      <span class=\"brand-mark\">CASA SHINDY</span>\n      <span class=\"brand-name\">BGM MIX STUDIO<span class=\"version-badge\">v16 CLEAN</span></span>\n    </div>\n\n    <div class=\"toolbar-group\">\n      <button id=\"btnImport\" class=\"btn btn-primary\">＋ 音源を追加</button>\n      <button id=\"btnAddEmptyTrack\" class=\"btn\" title=\"クリップの無い空のトラックを追加\">＋ 空トラック</button>\n      <input type=\"file\" id=\"fileInput\" accept=\"audio/*,.flac,.m4a,.aac,.ogg\" multiple class=\"hidden\" />\n    </div>\n\n    <div class=\"toolbar-sep\"></div>\n\n    <div class=\"toolbar-group transport\">\n      <button id=\"btnRewind\" class=\"btn btn-transport\" title=\"先頭に戻る (Home)\">|◀</button>\n      <button id=\"btnPlay\" class=\"btn btn-transport\" title=\"再生 / 一時停止 (Space)\">▶</button>\n      <button id=\"btnStop\" class=\"btn btn-transport\" title=\"停止\">■</button>\n      <span id=\"timeDisplay\" class=\"time-display\">00:00.0 / 00:00.0</span>\n      <label class=\"snap-toggle\"><input type=\"checkbox\" id=\"chkSnap\" checked /> スナップ 0.5秒</label>\n    </div>\n\n    <div class=\"toolbar-sep\"></div>\n\n    <div class=\"toolbar-group\">\n      <span class=\"ctl-label\">クロスフェード</span>\n      <input type=\"number\" id=\"xfadeSec\" class=\"ctl-num\" value=\"2\" min=\"0.2\" max=\"30\" step=\"0.5\" />\n      <span class=\"ctl-label\">秒</span>\n      <button id=\"btnAutoXfade\" class=\"btn\" title=\"全クリップを時刻順に並べ直し、隣同士を指定秒数だけ重ねて等パワーのクロスフェードを設定\">自動でつなぐ</button>\n    </div>\n\n    <div class=\"toolbar-sep\"></div>\n\n    <div class=\"toolbar-group meter-group\" title=\"マスター出力レベル (ピーク)\">\n      <span class=\"meter-label\">MASTER</span>\n      <div class=\"meter-bars\">\n        <div class=\"meter-track\"><div class=\"meter-fill\" id=\"meterFillL\"></div></div>\n        <div class=\"meter-track\"><div class=\"meter-fill\" id=\"meterFillR\"></div></div>\n      </div>\n      <button id=\"meterClip\" class=\"meter-clip-indicator\" title=\"0dBFS付近に達すると点灯。クリックでリセット\">CLIP</button>\n      <select id=\"masterPreset\" class=\"ctl\" title=\"マスターチェーンのプリセット\">\n        <option value=\"clean\" selected>Master: Clean</option>\n        <option value=\"glue\">Master: Glue</option>\n        <option value=\"studio\">Master: Studio</option>\n      </select>\n    </div>\n\n    <div class=\"toolbar-sep\"></div>\n\n    <div class=\"toolbar-group\">\n      <select id=\"exportFormat\" class=\"ctl\" title=\"書き出し形式\">\n        <option value=\"24\" selected>WAV 48k/24bit</option>\n        <option value=\"16\">WAV 48k/16bit (ディザ)</option>\n        <option value=\"32f\">WAV 48k/32bit float</option>\n        <option value=\"24-44\">WAV 44.1k/24bit</option>\n      </select>\n      <select id=\"exportLoudness\" class=\"ctl\" title=\"書き出し時のラウドネス正規化 (2パス書き出し)\">\n        <option value=\"off\" selected>音量正規化なし</option>\n        <option value=\"-16\">-16 LUFS</option>\n        <option value=\"-14\">-14 LUFS</option>\n        <option value=\"-11\">-11 LUFS</option>\n      </select>\n      <button id=\"btnExport\" class=\"btn btn-export\">↧ ミックスを書き出す</button>\n      <button id=\"btnExportSplit\" class=\"btn\" title=\"曲ごとの個別WAV + CUEシートも書き出す\">🔀 トラック分け</button>\n    </div>\n\n    <div class=\"toolbar-group\">\n      <button id=\"btnSaveProject\" class=\"btn\">プロジェクト保存</button>\n      <button id=\"btnLoadProject\" class=\"btn\">プロジェクトを開く</button>\n      <input type=\"file\" id=\"projectInput\" accept=\".json,application/json\" class=\"hidden\" />\n      <input type=\"file\" id=\"relinkInput\" accept=\"audio/*,.flac,.m4a,.aac,.ogg\" multiple class=\"hidden\" />\n    </div>\n  </header>\n\n  <div class=\"workspace\">\n    <div class=\"track-headers\" id=\"trackHeaders\">\n      <div class=\"ruler-spacer\">TRACKS — ドラッグ＆ドロップでも追加可</div>\n    </div>\n    <div class=\"timeline-scroll\" id=\"timelineScroll\">\n      <div class=\"timeline-inner\" id=\"timelineInner\">\n        <div class=\"ruler\" id=\"ruler\"></div>\n        <div class=\"tracks-container\" id=\"tracksContainer\">\n          <div class=\"playhead\" id=\"playhead\"></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <section id=\"inspector\">\n    <div class=\"insp-head\">\n      <span class=\"insp-title\">INSPECTOR <span class=\"accent\" id=\"inspTarget\">— トラックの FX ボタンか、クリップを選ぶとここに出ます</span></span>\n      <span class=\"insp-note\">EQ / フィルター / ディレイ / リバーブは再生しながら調整できます</span>\n      <button id=\"inspClose\" class=\"btn btn-small insp-close\">閉じる</button>\n    </div>\n    <div class=\"insp-body\" id=\"inspBody\">\n      <p class=\"insp-note\">音質の土台は作り直してあります: マスターは「DC除去 → (Glueコンプ) → リミッター → -1dBシーリング」、フェードは等パワー曲線、書き出しは24bit / ディザ付き16bit / 32bit float から選べます。まず音源を追加して、曲同士を重ねて「自動でつなぐ」を試してみてください。</p>\n    </div>\n  </section>\n\n  <footer class=\"statusbar\">\n    <span id=\"statusText\">音源を追加してください。ファイルをこの画面にドラッグ＆ドロップしても追加できます。</span>\n    <progress id=\"busyProgress\" class=\"hidden\" max=\"1\" value=\"0\"></progress>\n    <span>\n      <button id=\"zoomOut\" class=\"btn btn-small\">－</button>\n      表示倍率\n      <button id=\"zoomIn\" class=\"btn btn-small\">＋</button>\n    </span>\n  </footer>\n</div>\n\n<div id=\"clipContextMenu\" class=\"context-menu hidden\"></div>\n<div id=\"dropOverlay\" class=\"hidden\">音源ファイルをドロップして追加</div>\n\n<!-- ================= DSP CORE (pure functions, no DOM) ================= -->\n<script id=\"dsp-core\">\n'use strict';\n/* BGM MIX STUDIO v16 — DSP core.\n   Pure helpers shared by the live engine, the offline renderer and the tests.\n   Nothing in this block touches the DOM or a real AudioContext. */\n\nfunction clamp(v, lo, hi){ return Math.min(hi, Math.max(lo, v)); }\nfunction dbToGain(db){ return Math.pow(10, db / 20); }\nfunction gainToDb(g){ return g > 0 ? 20 * Math.log10(g) : -Infinity; }\n\n/* ---- Equal-power fades -------------------------------------------------\n   v15 and earlier used linear fades. Two uncorrelated signals crossfaded\n   linearly dip about 3-6 dB in the middle, and a linear fade-in sounds\n   like it \"rushes in at the end\". Equal-power (sin/cos) keeps the total\n   power constant: sin^2(x) + cos^2(x) = 1. */\nfunction equalPowerIn(x){ return Math.sin(clamp(x, 0, 1) * Math.PI / 2); }\nfunction equalPowerOut(x){ return Math.cos(clamp(x, 0, 1) * Math.PI / 2); }\n\n/* Gain of a clip at local time s (seconds from the clip's own start).\n   A 6 ms micro-fade is always folded in at both edges (de-click), even\n   when the user fade is 0 — hard cuts at a non-zero crossing click. */\nconst MICRO_FADE_SEC = 0.006;\nfunction clipGainAt(clipDuration, fadeIn, fadeOut, s){\n  if (s < 0 || s > clipDuration) return 0;\n  const fi = Math.max(fadeIn || 0, MICRO_FADE_SEC);\n  const fo = Math.max(fadeOut || 0, MICRO_FADE_SEC);\n  let g = 1;\n  if (s < fi) g *= equalPowerIn(s / fi);\n  if (s > clipDuration - fo) g *= equalPowerOut((s - (clipDuration - fo)) / fo);\n  return g;\n}\n/* Breakpoints for scheduling the envelope above with linear ramps.\n   Only the fade regions are subdivided (24 steps each is inaudible). */\nfunction clipEnvelopePoints(clipDuration, fadeIn, fadeOut){\n  const fi = Math.max(fadeIn || 0, MICRO_FADE_SEC);\n  const fo = Math.max(fadeOut || 0, MICRO_FADE_SEC);\n  const pts = [[0, clipGainAt(clipDuration, fadeIn, fadeOut, 0)]];\n  const N = 24;\n  for (let i = 1; i <= N; i++){\n    const s = fi * i / N;\n    if (s < clipDuration) pts.push([s, clipGainAt(clipDuration, fadeIn, fadeOut, s)]);\n  }\n  const outStart = clipDuration - fo;\n  for (let i = 1; i <= N; i++){\n    const s = outStart + fo * i / N;\n    if (s > fi && s <= clipDuration) pts.push([s, clipGainAt(clipDuration, fadeIn, fadeOut, s)]);\n  }\n  pts.push([clipDuration, clipGainAt(clipDuration, fadeIn, fadeOut, clipDuration)]);\n  pts.sort((a, b) => a[0] - b[0]);\n  return pts.filter((p, i) => i === 0 || p[0] - pts[i - 1][0] > 1e-4);\n}\n\n/* ---- WAV encoding -------------------------------------------------------\n   v15: 16-bit only, hard-clipped, truncated (no rounding, no dither).\n   v16: 16-bit with TPDF dither + rounding, 24-bit, or 32-bit float. */\nfunction encodeWAV(channels, sampleRate, format){\n  // format: 16 | 24 | '32f'\n  const numCh = channels.length;\n  const numFrames = channels[0].length;\n  const isFloat = format === '32f';\n  const bytesPerSample = isFloat ? 4 : (format === 24 ? 3 : 2);\n  const blockAlign = numCh * bytesPerSample;\n  const dataSize = numFrames * blockAlign;\n  const buf = new ArrayBuffer(44 + dataSize);\n  const view = new DataView(buf);\n  const wstr = (off, s) => { for (let i = 0; i < s.length; i++) view.setUint8(off + i, s.charCodeAt(i)); };\n  wstr(0, 'RIFF'); view.setUint32(4, 36 + dataSize, true); wstr(8, 'WAVE');\n  wstr(12, 'fmt '); view.setUint32(16, 16, true);\n  view.setUint16(20, isFloat ? 3 : 1, true);\n  view.setUint16(22, numCh, true);\n  view.setUint32(24, sampleRate, true);\n  view.setUint32(28, sampleRate * blockAlign, true);\n  view.setUint16(32, blockAlign, true);\n  view.setUint16(34, isFloat ? 32 : (format === 24 ? 24 : 16), true);\n  wstr(36, 'data'); view.setUint32(40, dataSize, true);\n  let off = 44;\n  for (let i = 0; i < numFrames; i++){\n    for (let c = 0; c < numCh; c++){\n      let s = clamp(channels[c][i], -1, 1);\n      if (isFloat){ view.setFloat32(off, s, true); off += 4; }\n      else if (format === 24){\n        const v = Math.round(s * 8388607);\n        view.setUint8(off, v & 0xff); view.setUint8(off + 1, (v >> 8) & 0xff); view.setUint8(off + 2, (v >> 16) & 0xff);\n        off += 3;\n      } else {\n        // TPDF dither: (r1 - r2) has a triangular distribution over +/-1 LSB.\n        const dither = (Math.random() - Math.random()) / 32768;\n        const v = clamp(Math.round((s + dither) * 32767), -32768, 32767);\n        view.setInt16(off, v, true); off += 2;\n      }\n    }\n  }\n  return buf;\n}\n\n/* ---- Loudness (approx. ITU-R BS.1770 K-weighting) ----------------------\n   Used only to stage the export gain; labelled approximate in the UI. */\nfunction kWeightingCoeffs(sr){\n  // Stage 1: high shelf (pre-filter), Stage 2: high-pass (RLB).\n  // Coefficients from the BS.1770 spec, computed for the given sample rate.\n  const f1 = 1681.974450955533, g1 = 3.999843853973347, q1 = 0.7071752369554196;\n  const f2 = 38.13547087602444, q2 = 0.5003270373238773;\n  const K1 = Math.tan(Math.PI * f1 / sr), Vh = Math.pow(10, g1 / 20), Vb = Math.pow(Vh, 0.4996667741545416);\n  const a0s = (Vh + Vb * K1 / q1 + K1 * K1) / (1 + K1 / q1 + K1 * K1);\n  const a1s = 2 * (K1 * K1 - Vh) / (1 + K1 / q1 + K1 * K1);\n  const a2s = (Vh - Vb * K1 / q1 + K1 * K1) / (1 + K1 / q1 + K1 * K1);\n  const b1s = 2 * (K1 * K1 - 1) / (1 + K1 / q1 + K1 * K1);\n  const b2s = (1 - K1 / q1 + K1 * K1) / (1 + K1 / q1 + K1 * K1);\n  const K2 = Math.tan(Math.PI * f2 / sr);\n  const a0h = 1, a1h = -2, a2h = 1;\n  const b1h = 2 * (K2 * K2 - 1) / (1 + K2 / q2 + K2 * K2);\n  const b2h = (1 - K2 / q2 + K2 * K2) / (1 + K2 / q2 + K2 * K2);\n  return { shelf: [a0s, a1s, a2s, b1s, b2s], hp: [a0h, a1h, a2h, b1h, b2h] };\n}\nfunction measureLoudness(channels, sampleRate){\n  const { shelf, hp } = kWeightingCoeffs(sampleRate);\n  let weightedMsSum = 0, peak = 0, totalSamples = 0;\n  for (let c = 0; c < channels.length; c++){\n    const data = channels[c];\n    let x1 = 0, x2 = 0, y1 = 0, y2 = 0;   // shelf state\n    let hx1 = 0, hx2 = 0, hy1 = 0, hy2 = 0; // hp state\n    let sumSq = 0;\n    for (let i = 0; i < data.length; i++){\n      const x = data[i];\n      const ax = Math.abs(x); if (ax > peak) peak = ax;\n      const y = shelf[0] * x + shelf[1] * x1 + shelf[2] * x2 - shelf[3] * y1 - shelf[4] * y2;\n      x2 = x1; x1 = x; y2 = y1; y1 = y;\n      const hy = hp[0] * y + hp[1] * hx1 + hp[2] * hx2 - hp[3] * hy1 - hp[4] * hy2;\n      hx2 = hx1; hx1 = y; hy2 = hy1; hy1 = hy;\n      sumSq += hy * hy;\n    }\n    weightedMsSum += sumSq / Math.max(1, data.length);\n    totalSamples = Math.max(totalSamples, data.length);\n  }\n  const lufs = weightedMsSum > 0 ? -0.691 + 10 * Math.log10(weightedMsSum) : -Infinity;\n  return { lufs, peak, peakDb: peak > 0 ? 20 * Math.log10(peak) : -Infinity, durationSec: totalSamples / sampleRate };\n}\n/* Gain (dB) to reach targetLufs without letting the sample peak pass ceilingDb. */\nfunction normalizeGainDb(measure, targetLufs, ceilingDb){\n  if (!isFinite(measure.lufs)) return 0;\n  const byLoudness = targetLufs - measure.lufs;\n  const byPeak = ceilingDb - measure.peakDb;\n  return Math.min(byLoudness, byPeak);\n}\n\n/* ---- Reverb impulse response -------------------------------------------\n   v15: raw white noise * pow() decay, convolver.normalize = true.\n   That gives a hissy, metallic tail whose level jumps with room size.\n   v16: noise through a one-pole low-pass whose cutoff *falls over time*\n   (real rooms lose high frequencies first), exponential-power decay\n   envelope with a short attack, and a fixed energy normalisation so the\n   wet level is predictable at any size. */\nfunction generateImpulseSamples(sampleRate, durationSec, decayPower){\n  const length = Math.max(1, Math.floor(sampleRate * durationSec));\n  const out = [new Float32Array(length), new Float32Array(length)];\n  const decay = decayPower || 2.6;\n  for (let ch = 0; ch < 2; ch++){\n    const data = out[ch];\n    let lp = 0;\n    for (let i = 0; i < length; i++){\n      const t = i / length;\n      const alpha = 0.88 * Math.pow(0.06, t); // damping increases as the tail decays\n      lp += alpha * ((Math.random() * 2 - 1) - lp);\n      const attack = 1 - Math.exp(-i / (sampleRate * 0.004));\n      data[i] = lp * Math.pow(1 - t, decay) * attack;\n    }\n  }\n  // Normalise to a fixed peak so wet gain means the same thing at any size.\n  let peak = 0;\n  for (let ch = 0; ch < 2; ch++) for (let i = 0; i < length; i++) peak = Math.max(peak, Math.abs(out[ch][i]));\n  if (peak > 0){ const k = 0.55 / peak; for (let ch = 0; ch < 2; ch++) for (let i = 0; i < length; i++) out[ch][i] *= k; }\n  return out;\n}\n\n/* ---- WSOLA time-stretch --------------------------------------------------\n   Same family as v15 (mono-reference alignment, so L/R never drift apart),\n   with normalised cross-correlation. Kept deliberately conservative:\n   hop 512 at a 4096 frame (87.5% overlap) is the quality/speed balance. */\nasync function timeStretchChannels(channelData, stretchRatio, onProgress){\n  const numChannels = channelData.length;\n  const inputLength = channelData[0].length;\n  const outputLength = Math.max(1, Math.round(inputLength * stretchRatio));\n  const frameSize = 4096, synthesisHop = 512;\n  const analysisHopIdeal = synthesisHop / stretchRatio;\n  const searchRadius = 448, overlapLen = frameSize - synthesisHop;\n  const win = new Float32Array(frameSize);\n  for (let i = 0; i < frameSize; i++) win[i] = 0.5 - 0.5 * Math.cos(2 * Math.PI * i / (frameSize - 1));\n  const mono = new Float32Array(inputLength);\n  for (let ch = 0; ch < numChannels; ch++){ const d = channelData[ch]; for (let i = 0; i < inputLength; i++) mono[i] += d[i] / numChannels; }\n  const outputs = [], weightSum = new Float32Array(outputLength + frameSize), monoSynth = new Float32Array(outputLength + frameSize);\n  for (let ch = 0; ch < numChannels; ch++) outputs.push(new Float32Array(outputLength + frameSize));\n  let synthesisPos = 0, analysisPos = 0, frameCount = 0;\n  while (synthesisPos < outputLength && analysisPos + frameSize < inputLength){\n    const searchCenter = Math.round(analysisPos);\n    let bestOffset = 0;\n    if (synthesisPos > 0){\n      let refEnergy = 0;\n      for (let k = 0; k < overlapLen; k += 2){ const a = monoSynth[synthesisPos + k]; refEnergy += a * a; }\n      const refNorm = Math.sqrt(refEnergy) + 1e-9;\n      let bestScore = -Infinity;\n      for (let off = -searchRadius; off <= searchRadius; off++){\n        const candStart = searchCenter + off;\n        if (candStart < 0 || candStart + overlapLen >= inputLength) continue;\n        let score = 0, candEnergy = 0;\n        for (let k = 0; k < overlapLen; k += 2){\n          const a = monoSynth[synthesisPos + k], b = mono[candStart + k];\n          score += a * b; candEnergy += b * b;\n        }\n        const ncc = score / (refNorm * (Math.sqrt(candEnergy) + 1e-9));\n        if (ncc > bestScore){ bestScore = ncc; bestOffset = off; }\n      }\n    }\n    const frameStart = clamp(searchCenter + bestOffset, 0, inputLength - 1);\n    const lim = Math.min(frameSize, inputLength - frameStart, outputs[0].length - synthesisPos);\n    for (let i = 0; i < lim; i++){\n      const w = win[i], outIdx = synthesisPos + i;\n      let monoSample = 0;\n      for (let ch = 0; ch < numChannels; ch++){\n        const s = channelData[ch][frameStart + i] * w;\n        outputs[ch][outIdx] += s; monoSample += s;\n      }\n      weightSum[outIdx] += w; monoSynth[outIdx] += monoSample / numChannels;\n    }\n    synthesisPos += synthesisHop; analysisPos += analysisHopIdeal; frameCount++;\n    if (onProgress && frameCount % 12 === 0){ onProgress(synthesisPos / outputLength); await new Promise(r => setTimeout(r, 0)); }\n  }\n  const result = [];\n  for (let ch = 0; ch < numChannels; ch++){\n    const out = new Float32Array(outputLength), src = outputs[ch];\n    for (let i = 0; i < outputLength; i++) out[i] = weightSum[i] > 1e-6 ? src[i] / weightSum[i] : 0;\n    result.push(out);\n  }\n  return result;\n}\n\n/* ---- BPM detection (onset-envelope autocorrelation) ----------------------\n   Deliberately simple and honest: works on clear-beat material, and the\n   confidence is just the autocorrelation peak strength. */\nfunction detectBpmFromChannels(channelData, sampleRate){\n  try {\n    const len = channelData[0].length;\n    const hopSec = 0.01, hop = Math.floor(sampleRate * hopSec);\n    const frames = Math.floor(len / hop);\n    if (frames < 300) return null;\n    const env = new Float32Array(frames);\n    let lp = 0;\n    for (let f = 0; f < frames; f++){\n      let e = 0;\n      for (let ch = 0; ch < channelData.length; ch++){\n        const d = channelData[ch];\n        for (let i = f * hop; i < (f + 1) * hop && i < len; i += 4){\n          lp += 0.22 * (d[i] - lp); // crude low-pass: beats live in the low end\n          e += lp * lp;\n        }\n      }\n      env[f] = e;\n    }\n    const onset = new Float32Array(frames);\n    for (let f = 1; f < frames; f++) onset[f] = Math.max(0, env[f] - env[f - 1]);\n    let mean = 0; for (let f = 0; f < frames; f++) mean += onset[f];\n    mean /= frames;\n    for (let f = 0; f < frames; f++) onset[f] = Math.max(0, onset[f] - mean);\n    const minLag = Math.floor(60 / 180 / hopSec), maxLag = Math.ceil(60 / 55 / hopSec);\n    let bestLag = -1, bestCorr = -Infinity, zeroCorr = 0;\n    for (let f = 0; f < frames; f++) zeroCorr += onset[f] * onset[f];\n    if (zeroCorr <= 0) return null;\n    for (let lag = minLag; lag <= maxLag; lag++){\n      let corr = 0;\n      for (let f = lag; f < frames; f++) corr += onset[f] * onset[f - lag];\n      corr /= zeroCorr;\n      if (corr > bestCorr){ bestCorr = corr; bestLag = lag; }\n    }\n    if (bestLag < 0) return null;\n    let bpm = 60 / (bestLag * hopSec);\n    while (bpm < 70) bpm *= 2;\n    while (bpm > 180) bpm /= 2;\n    return { bpm: Math.round(bpm), confidence: clamp(bestCorr, 0, 1) };\n  } catch (e){ return null; }\n}\n\nconst DSP = { clamp, dbToGain, gainToDb, equalPowerIn, equalPowerOut, clipGainAt, clipEnvelopePoints,\n  encodeWAV, measureLoudness, normalizeGainDb, generateImpulseSamples, timeStretchChannels,\n  detectBpmFromChannels, MICRO_FADE_SEC };\nif (typeof window !== 'undefined') window.DSP = DSP;\nif (typeof module !== 'undefined' && module.exports) module.exports = DSP;\n</script>\n\n<!-- ================= APP ================= -->\n<script>\n'use strict';\n/* BGM MIX STUDIO v16 CLEAN — application.\n   What changed for sound quality (details in the bundled README):\n   1. Master chain: DC-block -> optional glue comp -> optional gentle\n      saturation -> limiter -> -1 dB ceiling. v15 ran master gain 1.0\n      straight into the destination and hard-clipped the WAV export.\n   2. One graph builder for BOTH live playback and offline rendering,\n      so what you hear is exactly what you export.\n   3. Equal-power fades + a 6 ms de-click micro-fade on every clip edge.\n   4. The tone filter is in SERIES now. v15 mixed dry + filtered in\n      parallel, which comb-filters (phase cancellation) instead of EQing.\n   5. Delay repeats pass through a damping low-pass, and the feedback\n      is capped at 0.85, so echoes decay darker instead of stacking up\n      bright and harsh.\n   6. Reverb uses the damped, energy-normalised IR from the DSP core,\n      fed as a send (the dry signal never passes through the convolver).\n   7. Per-track 3-band EQ (serial shelves/peak, flat = transparent).\n   8. Export: 48 kHz, 24-bit by default, TPDF-dithered 16-bit, or\n      32-bit float; optional 2-pass loudness staging (approx. BS.1770)\n      with a -1 dB peak ceiling. */\n\nconst TRACK_COLORS = ['#d4a548', '#4fd1c5', '#e0605c', '#7c9fe0', '#b98be0', '#8bd17c', '#e0a97c', '#7ce0c9'];\nconst LANE_H = 96;\nconst SNAP_SEC = 0.5;\n\nlet uidCounter = 1;\nfunction uid(){ return 'id' + (uidCounter++) + Math.random().toString(36).slice(2, 7); }\nfunction escapeHtml(s){ return String(s == null ? '' : s).replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c])); }\nfunction fmtTime(sec){\n  if (!isFinite(sec) || sec < 0) sec = 0;\n  const m = Math.floor(sec / 60), s = sec - m * 60;\n  return String(m).padStart(2, '0') + ':' + s.toFixed(1).padStart(4, '0');\n}\n\n/* ---------------- state ---------------- */\nconst buffersById = new Map();   // sourceId -> { buffer, fileName }\nconst state = {\n  tracks: [],\n  pxPerSec: 40,\n  selectedClipIds: new Set(),\n  selectedTrackId: null,\n  isPlaying: false,\n  playStartCtxTime: 0,\n  playStartOffset: 0,\n  activeSources: [],\n  snap: true,\n  masterPreset: 'clean',\n};\nconst liveNodes = { master: null, tracks: new Map(), analysers: null };\nlet audioCtx = null;\n\nfunction createDefaultEffects(){\n  return {\n    eq: { low: 0, mid: 0, high: 0 },\n    filter: { enabled: false, type: 'lowpass', freq: 16000 },\n    delay: { enabled: false, timeSec: 0.38, feedback: 0.35, mix: 0.25 },\n    reverb: { enabled: false, mix: 0.25, size: 2.2 },\n  };\n}\nfunction normalizeEffects(saved){\n  const d = createDefaultEffects();\n  if (!saved) return d;\n  const out = {\n    eq: Object.assign({}, d.eq, saved.eq || {}),\n    filter: Object.assign({}, d.filter, saved.filter || {}),\n    delay: Object.assign({}, d.delay, saved.delay || {}),\n    reverb: Object.assign({}, d.reverb, saved.reverb || {}),\n  };\n  // v15 projects carried a ring modulator. It is intentionally dropped in\n  // v16 (a novelty effect that only ever damaged a clean mix).\n  return out;\n}\nfunction createTrack(name){\n  return { id: uid(), name: name || 'トラック', color: TRACK_COLORS[state.tracks.length % TRACK_COLORS.length],\n    volume: 0.9, pan: 0, muted: false, solo: false, effects: createDefaultEffects(), clips: [] };\n}\nfunction getTotalDuration(){\n  let max = 0;\n  state.tracks.forEach(t => t.clips.forEach(c => { max = Math.max(max, c.start + c.duration); }));\n  return max;\n}\nfunction getClipBuffer(clip){ const e = buffersById.get(clip.playSourceId || clip.sourceId); return e ? e.buffer : null; }\nfunction getTrack(id){ return state.tracks.find(t => t.id === id) || null; }\nfunction getSelectedClipEntry(){\n  if (state.selectedClipIds.size !== 1) return null;\n  const id = [...state.selectedClipIds][0];\n  for (const t of state.tracks){ const c = t.clips.find(x => x.id === id); if (c) return { track: t, clip: c }; }\n  return null;\n}\n\n/* ---------------- undo / redo ---------------- */\nconst undoStack = [], redoStack = [];\nfunction snapshotTracks(){ return JSON.stringify(state.tracks); }\nfunction pushUndo(){\n  undoStack.push(snapshotTracks());\n  if (undoStack.length > 60) undoStack.shift();\n  redoStack.length = 0;\n}\nfunction restoreTracks(json){\n  stopPlayback();\n  state.tracks = JSON.parse(json);\n  state.tracks.forEach(t => { t.effects = normalizeEffects(t.effects); });\n  state.selectedClipIds.clear();\n  disposeLiveTrackNodes();\n  renderAll();\n}\nfunction undo(){ if (!undoStack.length) return setStatus('これ以上元に戻せません。'); redoStack.push(snapshotTracks()); restoreTracks(undoStack.pop()); setStatus('元に戻しました。'); }\nfunction redo(){ if (!redoStack.length) return setStatus('やり直せる操作がありません。'); undoStack.push(snapshotTracks()); restoreTracks(redoStack.pop()); setStatus('やり直しました。'); }\n\n/* ---------------- master chain ----------------\n   input -> DC block (HP 24 Hz) -> [glue comp] -> [gentle saturation]\n         -> stage gain (export normalisation lives here) -> limiter\n         -> ceiling -1 dB -> output. */\nfunction buildMasterChain(ctx, preset, stageGainDb){\n  const input = ctx.createGain();\n  const hp = ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 24; hp.Q.value = 0.5;\n  input.connect(hp);\n  let head = hp;\n\n  let glue = null;\n  if (preset === 'glue' || preset === 'studio'){\n    glue = ctx.createDynamicsCompressor();\n    glue.threshold.value = -18; glue.knee.value = 18; glue.ratio.value = 2;\n    glue.attack.value = 0.012; glue.release.value = 0.24;\n    head.connect(glue); head = glue;\n  }\n  let saturator = null;\n  if (preset === 'studio'){\n    saturator = ctx.createWaveShaper();\n    const n = 512, curve = new Float32Array(n);\n    for (let i = 0; i < n; i++){ const x = i / (n - 1) * 2 - 1; curve[i] = Math.tanh(1.15 * x) / Math.tanh(1.15); }\n    saturator.curve = curve; saturator.oversample = '4x';\n    head.connect(saturator); head = saturator;\n  }\n  const stage = ctx.createGain(); stage.gain.value = DSP.dbToGain(stageGainDb || 0);\n  head.connect(stage);\n  const limiter = ctx.createDynamicsCompressor();\n  limiter.threshold.value = -1.2; limiter.knee.value = 0; limiter.ratio.value = 20;\n  limiter.attack.value = 0.002; limiter.release.value = 0.12;\n  stage.connect(limiter);\n  const ceiling = ctx.createGain(); ceiling.gain.value = DSP.dbToGain(-1.0);\n  limiter.connect(ceiling);\n  return { input, hp, glue, saturator, stage, limiter, ceiling, output: ceiling };\n}\n\n/* ---------------- per-track chain ----------------\n   clip bus -> EQ (low shelf / peak / high shelf, serial)\n            -> filter (serial; bypassed by parking a low-pass at 19.5 kHz)\n            -> fader -> panner -> master\n   Delay and reverb are SENDS off the panner output, so the dry path is\n   never coloured by them. The delay feedback loop contains a damping\n   low-pass, like an analogue echo. */\nconst irCache = new Map();\nfunction getImpulseBuffer(ctx, sizeSec){\n  const key = ctx.sampleRate + ':' + Math.round(sizeSec * 2) / 2;\n  if (!irCache.has(key)){\n    const samples = DSP.generateImpulseSamples(ctx.sampleRate, Math.round(sizeSec * 2) / 2, 2.6);\n    const buf = ctx.createBuffer(2, samples[0].length, ctx.sampleRate);\n    buf.copyToChannel(samples[0], 0); buf.copyToChannel(samples[1], 1);\n    irCache.set(key, buf);\n  }\n  return irCache.get(key);\n}\nfunction buildTrackChain(ctx, track, masterInput){\n  const fx = normalizeEffects(track.effects);\n  const clipBus = ctx.createGain();\n\n  const eqLow = ctx.createBiquadFilter(); eqLow.type = 'lowshelf'; eqLow.frequency.value = 120; eqLow.gain.value = fx.eq.low;\n  const eqMid = ctx.createBiquadFilter(); eqMid.type = 'peaking'; eqMid.frequency.value = 1000; eqMid.Q.value = 0.9; eqMid.gain.value = fx.eq.mid;\n  const eqHigh = ctx.createBiquadFilter(); eqHigh.type = 'highshelf'; eqHigh.frequency.value = 6500; eqHigh.gain.value = fx.eq.high;\n  clipBus.connect(eqLow); eqLow.connect(eqMid); eqMid.connect(eqHigh);\n\n  const filter = ctx.createBiquadFilter();\n  if (fx.filter.enabled){ filter.type = fx.filter.type; filter.frequency.value = fx.filter.freq; filter.Q.value = 0.7; }\n  else { filter.type = 'lowpass'; filter.frequency.value = 19500; filter.Q.value = 0.4; }\n  eqHigh.connect(filter);\n\n  const fader = ctx.createGain(); fader.gain.value = track.volume;\n  const panner = ctx.createStereoPanner(); panner.pan.value = track.pan;\n  filter.connect(fader); fader.connect(panner); panner.connect(masterInput);\n\n  // delay send (damped feedback)\n  const delaySend = ctx.createGain(); delaySend.gain.value = fx.delay.enabled ? fx.delay.mix : 0;\n  const delayNode = ctx.createDelay(4.0); delayNode.delayTime.value = DSP.clamp(fx.delay.timeSec, 0.02, 3.9);\n  const damp = ctx.createBiquadFilter(); damp.type = 'lowpass'; damp.frequency.value = 2600; damp.Q.value = 0.4;\n  const fb = ctx.createGain(); fb.gain.value = DSP.clamp(fx.delay.feedback, 0, 0.85);\n  const delayWet = ctx.createGain(); delayWet.gain.value = 1;\n  panner.connect(delaySend); delaySend.connect(delayNode);\n  delayNode.connect(damp); damp.connect(fb); fb.connect(delayNode);\n  delayNode.connect(delayWet); delayWet.connect(masterInput);\n\n  // reverb send\n  const revSend = ctx.createGain(); revSend.gain.value = fx.reverb.enabled ? fx.reverb.mix : 0;\n  const preDelay = ctx.createDelay(0.2); preDelay.delayTime.value = 0.018;\n  const convolver = ctx.createConvolver(); convolver.normalize = false; convolver.buffer = getImpulseBuffer(ctx, fx.reverb.size);\n  const revWet = ctx.createGain(); revWet.gain.value = 0.9;\n  panner.connect(revSend); revSend.connect(preDelay); preDelay.connect(convolver);\n  convolver.connect(revWet); revWet.connect(masterInput);\n\n  return { clipBus, eqLow, eqMid, eqHigh, filter, fader, panner, delaySend, delayNode, damp, fb, delayWet, revSend, preDelay, convolver, revWet, fxSnapshot: fx };\n}\nfunction applyTrackParamsLive(track){\n  const nodes = liveNodes.tracks.get(track.id);\n  if (!nodes || !audioCtx) return;\n  const fx = normalizeEffects(track.effects), t = audioCtx.currentTime, tc = 0.03;\n  nodes.eqLow.gain.setTargetAtTime(fx.eq.low, t, tc);\n  nodes.eqMid.gain.setTargetAtTime(fx.eq.mid, t, tc);\n  nodes.eqHigh.gain.setTargetAtTime(fx.eq.high, t, tc);\n  if (fx.filter.enabled){\n    nodes.filter.type = fx.filter.type;\n    nodes.filter.frequency.setTargetAtTime(fx.filter.freq, t, tc);\n  } else {\n    nodes.filter.type = 'lowpass';\n    nodes.filter.frequency.setTargetAtTime(19500, t, tc);\n  }\n  const anySolo = state.tracks.some(x => x.solo);\n  const audible = anySolo ? track.solo : !track.muted;\n  nodes.fader.gain.setTargetAtTime(audible ? track.volume : 0, t, tc);\n  nodes.panner.pan.setTargetAtTime(track.pan, t, tc);\n  nodes.delayNode.delayTime.setTargetAtTime(DSP.clamp(fx.delay.timeSec, 0.02, 3.9), t, tc);\n  nodes.fb.gain.setTargetAtTime(DSP.clamp(fx.delay.feedback, 0, 0.85), t, tc);\n  nodes.delaySend.gain.setTargetAtTime(fx.delay.enabled ? fx.delay.mix : 0, t, tc);\n  nodes.revSend.gain.setTargetAtTime(fx.reverb.enabled ? fx.reverb.mix : 0, t, tc);\n  if (Math.abs((nodes.fxSnapshot.reverb.size || 2.2) - fx.reverb.size) > 0.24){\n    nodes.convolver.buffer = getImpulseBuffer(audioCtx, fx.reverb.size);\n  }\n  nodes.fxSnapshot = fx;\n}\nfunction disposeLiveTrackNodes(){\n  liveNodes.tracks.forEach(nodes => {\n    Object.values(nodes).forEach(n => { if (n && typeof n.disconnect === 'function'){ try { n.disconnect(); } catch (e){} } });\n  });\n  liveNodes.tracks.clear();\n}\nfunction ensureLiveGraph(){\n  const ctx = getAudioCtx();\n  if (!liveNodes.master){\n    liveNodes.master = buildMasterChain(ctx, state.masterPreset, 0);\n    liveNodes.master.output.connect(ctx.destination);\n    const splitter = ctx.createChannelSplitter(2);\n    liveNodes.master.output.connect(splitter);\n    const aL = ctx.createAnalyser(), aR = ctx.createAnalyser();\n    aL.fftSize = 1024; aR.fftSize = 1024;\n    splitter.connect(aL, 0); splitter.connect(aR, 1);\n    liveNodes.analysers = { aL, aR };\n    startMeterLoop();\n  }\n  // drop nodes for deleted tracks, add nodes for new ones\n  [...liveNodes.tracks.keys()].forEach(id => { if (!getTrack(id)){ const n = liveNodes.tracks.get(id); Object.values(n).forEach(x => { if (x && x.disconnect) try { x.disconnect(); } catch (e){} }); liveNodes.tracks.delete(id); } });\n  state.tracks.forEach(track => {\n    if (!liveNodes.tracks.has(track.id)){\n      liveNodes.tracks.set(track.id, buildTrackChain(ctx, track, liveNodes.master.input));\n    }\n    applyTrackParamsLive(track);\n  });\n}\nfunction rebuildLiveMaster(){\n  if (!audioCtx || !liveNodes.master) return;\n  const wasPlaying = state.isPlaying, pos = getCurrentTimelinePosition();\n  if (wasPlaying) pausePlayback();\n  try { liveNodes.master.output.disconnect(); } catch (e){}\n  disposeLiveTrackNodes();\n  liveNodes.master = null; liveNodes.analysers = null;\n  ensureLiveGraph();\n  if (wasPlaying) schedulePlaybackFrom(pos);\n}\nfunction getAudioCtx(){\n  if (!audioCtx){\n    audioCtx = new (window.AudioContext || window.webkitAudioContext)({ latencyHint: 'interactive' });\n  }\n  return audioCtx;\n}\n\n/* ---------------- level meter ---------------- */\nlet lastClipAt = 0;\nfunction startMeterLoop(){\n  const fillL = document.getElementById('meterFillL'), fillR = document.getElementById('meterFillR');\n  const clipBtn = document.getElementById('meterClip');\n  if (!fillL || !liveNodes.analysers) return;\n  const buf = new Float32Array(1024);\n  let dispL = 0, dispR = 0;\n  function peakOf(a){ a.getFloatTimeDomainData(buf); let p = 0; for (let i = 0; i < buf.length; i++){ const v = Math.abs(buf[i]); if (v > p) p = v; } return p; }\n  function show(el, peak){\n    const db = peak > 0 ? 20 * Math.log10(peak) : -60;\n    el.style.width = DSP.clamp((db + 45) * (100 / 45), 0, 100) + '%';\n    return peak >= 0.989;\n  }\n  (function tick(){\n    if (!liveNodes.analysers) return;\n    dispL = Math.max(peakOf(liveNodes.analysers.aL), dispL * 0.86);\n    dispR = Math.max(peakOf(liveNodes.analysers.aR), dispR * 0.86);\n    const clipped = show(fillL, dispL) | show(fillR, dispR);\n    if (clipped) lastClipAt = performance.now();\n    if (clipBtn) clipBtn.classList.toggle('active', performance.now() - lastClipAt < 1500);\n    requestAnimationFrame(tick);\n  })();\n}\n\n/* ---------------- playback ---------------- */\nfunction scheduleEnvelope(param, ctxStartTime, clip, playFromTimeline){\n  const localFrom = Math.max(0, playFromTimeline - clip.start);\n  const pts = DSP.clipEnvelopePoints(clip.duration, clip.fadeIn, clip.fadeOut);\n  param.cancelScheduledValues(ctxStartTime);\n  param.setValueAtTime(Math.max(0.0001, DSP.clipGainAt(clip.duration, clip.fadeIn, clip.fadeOut, localFrom)), ctxStartTime);\n  pts.forEach(([localT, g]) => {\n    if (localT > localFrom + 0.001){\n      param.linearRampToValueAtTime(Math.max(0.0001, g), ctxStartTime + (localT - localFrom));\n    }\n  });\n}\nfunction stopActiveSources(){\n  state.activeSources.forEach(src => { try { src.stop(); } catch (e){} try { src.disconnect(); } catch (e){} });\n  state.activeSources = [];\n}\nfunction scheduleClipInto(ctx, destinationNode, track, clip, windowStart, ctxBaseTime, windowEnd){\n  const buffer = getClipBuffer(clip);\n  if (!buffer) return null;\n  const clipEnd = clip.start + clip.duration;\n  if (clipEnd <= windowStart) return null;\n  if (windowEnd != null && clip.start >= windowEnd) return null; // segment renders must not pull in later songs\n  let startDelay, bufferOffset, playDuration, envelopeFrom;\n  if (clip.start >= windowStart){ startDelay = clip.start - windowStart; bufferOffset = clip.offset; playDuration = clip.duration; envelopeFrom = clip.start; }\n  else { startDelay = 0; const skipped = windowStart - clip.start; bufferOffset = clip.offset + skipped; playDuration = clip.duration - skipped; envelopeFrom = windowStart; }\n  if (playDuration <= 0.01) return null;\n  const src = ctx.createBufferSource(); src.buffer = buffer;\n  const clipGain = ctx.createGain();\n  src.connect(clipGain); clipGain.connect(destinationNode);\n  scheduleEnvelope(clipGain.gain, ctxBaseTime + startDelay, clip, envelopeFrom);\n  try { src.start(ctxBaseTime + startDelay, Math.max(0, bufferOffset), Math.max(0.01, playDuration)); } catch (e){ return null; }\n  return src;\n}\nfunction schedulePlaybackFrom(fromTime){\n  const ctx = getAudioCtx();\n  if (ctx.state === 'suspended') ctx.resume();\n  ensureLiveGraph();\n  stopActiveSources();\n  const startCtxTime = ctx.currentTime + 0.08;\n  const anySolo = state.tracks.some(t => t.solo);\n  state.tracks.forEach(track => {\n    const audible = anySolo ? track.solo : !track.muted;\n    if (!audible) return;\n    const nodes = liveNodes.tracks.get(track.id);\n    if (!nodes) return;\n    track.clips.forEach(clip => {\n      const src = scheduleClipInto(ctx, nodes.clipBus, track, clip, fromTime, startCtxTime);\n      if (src) state.activeSources.push(src);\n    });\n  });\n  state.isPlaying = true;\n  state.playStartCtxTime = startCtxTime;\n  state.playStartOffset = fromTime;\n  document.getElementById('btnPlay').textContent = '❚❚';\n  requestAnimationFrame(playbackTick);\n}\nfunction getCurrentTimelinePosition(){\n  if (!state.isPlaying || !audioCtx) return state.playStartOffset;\n  return state.playStartOffset + (audioCtx.currentTime - state.playStartCtxTime);\n}\nfunction pausePlayback(){\n  if (!state.isPlaying) return;\n  state.playStartOffset = getCurrentTimelinePosition();\n  stopActiveSources();\n  state.isPlaying = false;\n  document.getElementById('btnPlay').textContent = '▶';\n}\nfunction stopPlayback(){\n  stopActiveSources();\n  state.isPlaying = false;\n  state.playStartOffset = 0;\n  const btn = document.getElementById('btnPlay'); if (btn) btn.textContent = '▶';\n  updatePlayhead(0); updateTimeDisplay();\n}\nfunction seekTo(t){\n  const was = state.isPlaying;\n  if (was) stopActiveSources();\n  state.isPlaying = false;\n  state.playStartOffset = Math.max(0, t);\n  updatePlayhead(state.playStartOffset); updateTimeDisplay();\n  if (was) schedulePlaybackFrom(state.playStartOffset);\n}\nfunction togglePlay(){\n  if (state.isPlaying) pausePlayback();\n  else {\n    if (getTotalDuration() <= 0) return setStatus('まず音源を追加してください。');\n    schedulePlaybackFrom(state.playStartOffset || 0);\n  }\n}\nfunction playbackTick(){\n  if (!state.isPlaying) return;\n  const pos = getCurrentTimelinePosition();\n  updatePlayhead(pos); updateTimeDisplay();\n  if (pos >= getTotalDuration() + 0.05){ stopPlayback(); return; }\n  requestAnimationFrame(playbackTick);\n}\nfunction updatePlayhead(t){\n  const el = document.getElementById('playhead');\n  if (el) el.style.left = (t * state.pxPerSec) + 'px';\n}\nfunction updateTimeDisplay(){\n  const el = document.getElementById('timeDisplay');\n  if (el) el.textContent = fmtTime(getCurrentTimelinePosition()) + ' / ' + fmtTime(getTotalDuration());\n}\n\n/* ---------------- offline rendering ----------------\n   Identical builders to the live path — the export is the same mix. */\nfunction fxTailSeconds(){\n  let tail = 0.4;\n  state.tracks.forEach(t => {\n    const fx = normalizeEffects(t.effects);\n    if (fx.reverb.enabled) tail = Math.max(tail, Math.min(6, fx.reverb.size + 1.2));\n    if (fx.delay.enabled) tail = Math.max(tail, Math.min(6, fx.delay.timeSec * (1 + fx.delay.feedback * 6)));\n  });\n  return tail;\n}\nasync function renderMixWindow(windowStart, windowEnd, opts){\n  const sampleRate = (opts && opts.sampleRate) || 48000;\n  const stageGainDb = (opts && opts.stageGainDb) || 0;\n  const duration = Math.max(0.05, windowEnd - windowStart);\n  const tail = fxTailSeconds();\n  const offline = new OfflineAudioContext(2, Math.ceil((duration + tail) * sampleRate), sampleRate);\n  const master = buildMasterChain(offline, state.masterPreset, stageGainDb);\n  master.output.connect(offline.destination);\n  const anySolo = state.tracks.some(t => t.solo);\n  state.tracks.forEach(track => {\n    const audible = anySolo ? track.solo : !track.muted;\n    if (!audible) return;\n    const chain = buildTrackChain(offline, track, master.input);\n    // offline chains are built with the track's static fader/pan values;\n    // mute/solo are already applied by the audible check above.\n    track.clips.forEach(clip => { scheduleClipInto(offline, chain.clipBus, track, clip, windowStart, 0, windowEnd); });\n  });\n  const rendered = await offline.startRendering();\n  return { buffer: rendered, tailSeconds: tail, contentSeconds: duration };\n}\nfunction downloadBlob(blob, fileName){\n  if (window.electronAPI && window.electronAPI.exportWav && blob.type === 'audio/wav'){\n    blob.arrayBuffer().then(ab => window.electronAPI.exportWav({ defaultName: fileName, arrayBuffer: ab }));\n    return;\n  }\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement('a');\n  a.href = url; a.download = fileName;\n  document.body.appendChild(a); a.click(); a.remove();\n  setTimeout(() => URL.revokeObjectURL(url), 4000);\n}\nfunction exportSettings(){\n  const fmtSel = document.getElementById('exportFormat').value;\n  const sampleRate = fmtSel === '24-44' ? 44100 : 48000;\n  const format = fmtSel === '32f' ? '32f' : (fmtSel === '16' ? 16 : 24);\n  const loudSel = document.getElementById('exportLoudness').value;\n  return { sampleRate, format, targetLufs: loudSel === 'off' ? null : parseFloat(loudSel) };\n}\nasync function renderFinal(windowStart, windowEnd, settings, statusPrefix){\n  // Pass 1: measure. Pass 2 (only when normalising): re-render through\n  // the limiter with the staging gain, so peaks are handled by the\n  // limiter rather than by hard clipping in the encoder.\n  setStatus(statusPrefix + 'レンダリング中…');\n  let rendered = await renderMixWindow(windowStart, windowEnd, { sampleRate: settings.sampleRate, stageGainDb: 0 });\n  let channels = [rendered.buffer.getChannelData(0), rendered.buffer.getChannelData(1)];\n  let note = '';\n  if (settings.targetLufs != null){\n    const m = DSP.measureLoudness(channels, settings.sampleRate);\n    const gainDb = DSP.normalizeGainDb(m, settings.targetLufs, -1.0);\n    note = ' (測定 ' + (isFinite(m.lufs) ? m.lufs.toFixed(1) : '—') + ' LUFS / ピーク ' + (isFinite(m.peakDb) ? m.peakDb.toFixed(1) : '—') + ' dB → ' + (gainDb >= 0 ? '+' : '') + gainDb.toFixed(1) + ' dB)';\n    if (Math.abs(gainDb) > 0.05){\n      setStatus(statusPrefix + '音量を揃えて再レンダリング中…' + note);\n      rendered = await renderMixWindow(windowStart, windowEnd, { sampleRate: settings.sampleRate, stageGainDb: gainDb });\n      channels = [rendered.buffer.getChannelData(0), rendered.buffer.getChannelData(1)];\n    }\n  }\n  return { wav: DSP.encodeWAV(channels, settings.sampleRate, settings.format), note };\n}\nasync function handleExport(){\n  const total = getTotalDuration();\n  if (total <= 0) return setStatus('書き出す音源がありません。');\n  const btn = document.getElementById('btnExport'); btn.disabled = true;\n  try {\n    const settings = exportSettings();\n    const { wav, note } = await renderFinal(0, total, settings, 'ミックスダウン: ');\n    const name = 'bgm_mix_' + new Date().toISOString().slice(0, 10) + '.wav';\n    downloadBlob(new Blob([wav], { type: 'audio/wav' }), name);\n    setStatus('書き出し完了: ' + name + note + ' — ' + settings.sampleRate / 1000 + 'kHz / ' + (settings.format === '32f' ? '32bit float' : settings.format + 'bit'));\n  } catch (err){ console.error(err); setStatus('⚠ 書き出しに失敗しました: ' + err.message); }\n  btn.disabled = false;\n}\nfunction computeSegments(){\n  const clips = [];\n  state.tracks.forEach(t => t.clips.forEach(c => clips.push(c)));\n  if (!clips.length) return [];\n  const total = getTotalDuration();\n  const starts = [...new Set(clips.map(c => Math.round(c.start * 100) / 100))].sort((a, b) => a - b);\n  const segments = [];\n  for (let i = 0; i < starts.length; i++){\n    const segStart = starts[i], segEnd = i + 1 < starts.length ? starts[i + 1] : total;\n    if (segEnd - segStart < 0.05) continue;\n    const starting = clips.filter(c => Math.abs(c.start - segStart) < 0.05).sort((a, b) => a.start - b.start)[0] || clips[0];\n    segments.push({ index: segments.length + 1, start: segStart, end: segEnd, label: (starting.fileName || 'track').replace(/\\.[^/.]+$/, '') });\n  }\n  return segments;\n}\nfunction formatCueTime(sec){\n  const totalFrames = Math.round(sec * 75);\n  const mm = Math.floor(totalFrames / 4500), ss = Math.floor((totalFrames % 4500) / 75), ff = totalFrames % 75;\n  return String(mm).padStart(2, '0') + ':' + String(ss).padStart(2, '0') + ':' + String(ff).padStart(2, '0');\n}\nasync function handleExportSplit(){\n  const total = getTotalDuration();\n  if (total <= 0) return setStatus('書き出す音源がありません。');\n  const segments = computeSegments();\n  if (!segments.length) return setStatus('分割できるクリップがありません。');\n  const btn = document.getElementById('btnExportSplit'); btn.disabled = true;\n  try {\n    const settings = exportSettings();\n    const full = await renderFinal(0, total, settings, 'フルミックス: ');\n    downloadBlob(new Blob([full.wav], { type: 'audio/wav' }), 'full_mix.wav');\n    for (const seg of segments){\n      await new Promise(r => setTimeout(r, 350)); // let each download start before the next\n      const part = await renderFinal(seg.start, seg.end, settings, 'トラック ' + seg.index + '/' + segments.length + ': ');\n      const safe = seg.label.replace(/[\\\\/:*?\"<>|]/g, '_').slice(0, 60);\n      downloadBlob(new Blob([part.wav], { type: 'audio/wav' }), String(seg.index).padStart(2, '0') + '_' + safe + '.wav');\n    }\n    const cue = ['FILE \"full_mix.wav\" WAVE'].concat(segments.map(s =>\n      '  TRACK ' + String(s.index).padStart(2, '0') + ' AUDIO\\n    TITLE \"' + s.label.replace(/\"/g, '') + '\"\\n    INDEX 01 ' + formatCueTime(s.start)\n    )).join('\\n');\n    downloadBlob(new Blob([cue], { type: 'text/plain' }), 'mix.cue');\n    setStatus('トラック分け書き出し完了: フルミックス + ' + segments.length + 'トラック + CUEシート (ブラウザのダウンロードに複数ファイルが入ります)');\n  } catch (err){ console.error(err); setStatus('⚠ トラック分け書き出しに失敗しました: ' + err.message); }\n  btn.disabled = false;\n}\n\n/* ---------------- status / helpers ---------------- */\nfunction setStatus(msg){ const el = document.getElementById('statusText'); if (el) el.textContent = msg; }\nfunction setBusy(frac){\n  const p = document.getElementById('busyProgress');\n  if (!p) return;\n  if (frac == null){ p.classList.add('hidden'); }\n  else { p.classList.remove('hidden'); p.value = frac; }\n}\nfunction pushUndoWithSnapshot(snap){\n  undoStack.push(snap);\n  if (undoStack.length > 60) undoStack.shift();\n  redoStack.length = 0;\n}\n\n/* ---------------- waveforms ---------------- */\nconst peaksCache = new Map();\nfunction getPeaks(sourceId){\n  if (peaksCache.has(sourceId)) return peaksCache.get(sourceId);\n  const entry = buffersById.get(sourceId);\n  if (!entry) return null;\n  const buf = entry.buffer, N = 2048, peaks = new Float32Array(N);\n  const chans = [];\n  for (let c = 0; c < buf.numberOfChannels; c++) chans.push(buf.getChannelData(c));\n  const per = Math.max(1, Math.floor(buf.length / N));\n  for (let b = 0; b < N; b++){\n    let m = 0; const start = b * per;\n    for (let c = 0; c < chans.length; c++){\n      const d = chans[c];\n      for (let i = start; i < Math.min(buf.length, start + per); i += 7){ const v = Math.abs(d[i]); if (v > m) m = v; }\n    }\n    peaks[b] = m;\n  }\n  peaksCache.set(sourceId, peaks);\n  return peaks;\n}\nfunction drawWaveform(canvas, clip, color){\n  const w = Math.max(10, Math.floor(canvas.clientWidth * (window.devicePixelRatio || 1)));\n  const h = Math.max(10, Math.floor(canvas.clientHeight * (window.devicePixelRatio || 1)));\n  if (canvas.width !== w) canvas.width = w;\n  if (canvas.height !== h) canvas.height = h;\n  const g = canvas.getContext && canvas.getContext('2d');\n  if (!g) return;\n  g.clearRect(0, 0, w, h);\n  const peaks = getPeaks(clip.playSourceId || clip.sourceId);\n  g.fillStyle = 'rgba(10,10,12,0.55)'; g.fillRect(0, 0, w, h);\n  if (!peaks) return;\n  const buf = getClipBuffer(clip);\n  if (!buf) return;\n  const mid = h / 2;\n  g.fillStyle = color;\n  for (let x = 0; x < w; x++){\n    const t0 = clip.offset + (x / w) * clip.duration;\n    const idx = DSP.clamp(Math.floor(t0 / buf.duration * peaks.length), 0, peaks.length - 1);\n    const amp = Math.max(0.02, peaks[idx]) * (mid - 3);\n    g.fillRect(x, mid - amp, 1, amp * 2);\n  }\n  g.fillStyle = 'rgba(255,255,255,0.25)'; g.fillRect(0, mid, w, 1);\n}\n\n/* ---------------- rendering ---------------- */\nfunction timelineWidthSec(){ return Math.max(getTotalDuration() + 30, 120); }\nfunction renderRuler(){\n  const ruler = document.getElementById('ruler');\n  ruler.innerHTML = '';\n  ruler.style.width = (timelineWidthSec() * state.pxPerSec) + 'px';\n  const step = state.pxPerSec >= 90 ? 1 : state.pxPerSec >= 38 ? 5 : state.pxPerSec >= 16 ? 10 : 30;\n  for (let t = 0; t <= timelineWidthSec(); t += step){\n    const tick = document.createElement('div');\n    tick.className = 'ruler-tick';\n    tick.style.left = (t * state.pxPerSec) + 'px';\n    tick.style.width = (step * state.pxPerSec) + 'px';\n    tick.textContent = fmtTime(t);\n    ruler.appendChild(tick);\n  }\n}\nfunction renderTrackHeaders(){\n  const container = document.getElementById('trackHeaders');\n  container.querySelectorAll('.track-header').forEach(el => el.remove());\n  state.tracks.forEach(track => {\n    const el = document.createElement('div');\n    el.className = 'track-header' + (state.selectedTrackId === track.id ? ' selected' : '');\n    const anySolo = state.tracks.some(t => t.solo);\n    const refClip = track.clips[0];\n    el.innerHTML =\n      '<div class=\"th-top\"><span class=\"th-color\" style=\"background:' + track.color + '\"></span>' +\n      '<span class=\"th-name\" title=\"' + escapeHtml(track.name) + '\">' + escapeHtml(track.name) + '</span>' +\n      '<button class=\"th-icon-btn\" data-act=\"dup\" title=\"トラックを複製\">⧉</button>' +\n      '<button class=\"th-icon-btn\" data-act=\"del\" title=\"トラックを削除\">🗑</button></div>' +\n      '<div class=\"th-row\"><label>音量</label><input type=\"range\" class=\"th-fader\" min=\"0\" max=\"1.25\" step=\"0.01\" value=\"' + track.volume + '\" />' +\n      '<span class=\"th-val\">' + Math.round(track.volume * 100) + '%</span></div>' +\n      '<div class=\"th-row\"><label>PAN</label><input type=\"range\" class=\"th-pan\" min=\"-1\" max=\"1\" step=\"0.01\" value=\"' + track.pan + '\" />' +\n      '<span class=\"th-val\">' + (track.pan === 0 ? 'C' : track.pan < 0 ? 'L' + Math.round(-track.pan * 100) : 'R' + Math.round(track.pan * 100)) + '</span></div>' +\n      '<div class=\"th-btns\">' +\n      '<button class=\"th-btn th-mute' + (track.muted ? ' active-m' : '') + '\">M</button>' +\n      '<button class=\"th-btn th-solo' + (track.solo ? ' active-s' : '') + '\">S</button>' +\n      '<button class=\"th-btn th-fx' + (state.selectedTrackId === track.id ? ' active-fx' : '') + '\">FX / EQ</button>' +\n      (refClip && refClip.detectedBpm ? '<span class=\"th-bpm\">♩' + refClip.detectedBpm + (refClip.targetBpm && refClip.targetBpm !== refClip.detectedBpm ? ' → ' + refClip.targetBpm : '') + '</span>' : '') +\n      '</div>';\n    el.addEventListener('click', () => { state.selectedTrackId = track.id; renderTrackHeaders(); });\n    el.querySelector('[data-act=\"del\"]').addEventListener('click', (e) => {\n      e.stopPropagation();\n      if (!confirm('トラック「' + track.name + '」を削除しますか？')) return;\n      pushUndo(); stopPlayback();\n      state.tracks = state.tracks.filter(t => t.id !== track.id);\n      disposeLiveTrackNodes(); renderAll();\n    });\n    el.querySelector('[data-act=\"dup\"]').addEventListener('click', (e) => {\n      e.stopPropagation(); pushUndo();\n      const copy = JSON.parse(JSON.stringify(track));\n      copy.id = uid(); copy.name = track.name + ' (複製)';\n      copy.clips.forEach(c => { c.id = uid(); });\n      state.tracks.splice(state.tracks.indexOf(track) + 1, 0, copy);\n      renderAll(); setStatus('トラックを複製しました。');\n    });\n    const fader = el.querySelector('.th-fader');\n    fader.addEventListener('input', () => {\n      track.volume = parseFloat(fader.value);\n      el.querySelectorAll('.th-val')[0].textContent = Math.round(track.volume * 100) + '%';\n      applyTrackParamsLive(track);\n    });\n    fader.addEventListener('click', e => e.stopPropagation());\n    const pan = el.querySelector('.th-pan');\n    pan.addEventListener('input', () => {\n      track.pan = parseFloat(pan.value);\n      el.querySelectorAll('.th-val')[1].textContent = track.pan === 0 ? 'C' : track.pan < 0 ? 'L' + Math.round(-track.pan * 100) : 'R' + Math.round(track.pan * 100);\n      applyTrackParamsLive(track);\n    });\n    pan.addEventListener('click', e => e.stopPropagation());\n    el.querySelector('.th-mute').addEventListener('click', (e) => { e.stopPropagation(); track.muted = !track.muted; applyTrackParamsLive(track); renderTrackHeaders(); });\n    el.querySelector('.th-solo').addEventListener('click', (e) => { e.stopPropagation(); track.solo = !track.solo; state.tracks.forEach(applyTrackParamsLive); renderTrackHeaders(); });\n    el.querySelector('.th-fx').addEventListener('click', (e) => { e.stopPropagation(); state.selectedTrackId = track.id; showInspector(track, null); renderTrackHeaders(); });\n    container.appendChild(el);\n  });\n}\nfunction renderClips(){\n  const container = document.getElementById('tracksContainer');\n  container.querySelectorAll('.track-lane').forEach(el => el.remove());\n  container.style.width = (timelineWidthSec() * state.pxPerSec) + 'px';\n  state.tracks.forEach((track, ti) => {\n    const lane = document.createElement('div');\n    lane.className = 'track-lane';\n    lane.dataset.track = track.id;\n    lane.style.top = '0';\n    track.clips.forEach(clip => lane.appendChild(buildClipElement(track, clip)));\n    container.appendChild(lane);\n    lane.addEventListener('mousedown', (e) => {\n      if (e.target !== lane) return;\n      const rect = lane.getBoundingClientRect();\n      seekTo(Math.max(0, (e.clientX - rect.left) / state.pxPerSec));\n    });\n  });\n  updatePlayhead(getCurrentTimelinePosition());\n}\nfunction buildClipElement(track, clip){\n  const el = document.createElement('div');\n  el.className = 'clip' + (state.selectedClipIds.has(clip.id) ? ' selected' : '');\n  el.dataset.clip = clip.id;\n  el.style.left = (clip.start * state.pxPerSec) + 'px';\n  el.style.width = Math.max(14, clip.duration * state.pxPerSec) + 'px';\n  el.style.background = track.color + '33';\n  el.style.borderColor = track.color;\n  const canvas = document.createElement('canvas');\n  el.appendChild(canvas);\n  const label = document.createElement('div');\n  label.className = 'clip-label'; label.textContent = clip.fileName || track.name;\n  el.appendChild(label);\n  if (clip.detectedBpm){\n    const bpm = document.createElement('div');\n    bpm.className = 'clip-bpm';\n    bpm.textContent = '♩' + clip.detectedBpm + (clip.targetBpm && clip.targetBpm !== clip.detectedBpm ? '→' + clip.targetBpm : '');\n    el.appendChild(bpm);\n  }\n  if (clip.fadeIn > 0.02 || clip.fadeOut > 0.02){\n    const badge = document.createElement('div');\n    badge.className = 'clip-xfade-badge';\n    badge.textContent = 'fade ' + (clip.fadeIn || 0).toFixed(1) + ' / ' + (clip.fadeOut || 0).toFixed(1);\n    el.appendChild(badge);\n  }\n  ['in', 'out'].forEach(which => {\n    const shade = document.createElement('div');\n    shade.className = 'fade-shade ' + which;\n    const fadeSec = which === 'in' ? clip.fadeIn : clip.fadeOut;\n    shade.style.width = Math.min(60, (fadeSec / Math.max(0.01, clip.duration)) * 100) + '%';\n    el.appendChild(shade);\n  });\n  if (clip.offset > 0.01){ const m = document.createElement('div'); m.className = 'more-mark left'; m.textContent = '«'; el.appendChild(m); }\n  if (clip.offset + clip.duration < clip.sourceDuration - 0.01){ const m = document.createElement('div'); m.className = 'more-mark right'; m.textContent = '»'; el.appendChild(m); }\n  const trimL = document.createElement('div'); trimL.className = 'trim-handle left'; el.appendChild(trimL);\n  const trimR = document.createElement('div'); trimR.className = 'trim-handle right'; el.appendChild(trimR);\n  const fadeInH = document.createElement('div'); fadeInH.className = 'fade-handle in'; el.appendChild(fadeInH);\n  const fadeOutH = document.createElement('div'); fadeOutH.className = 'fade-handle out'; el.appendChild(fadeOutH);\n  requestAnimationFrame(() => drawWaveform(canvas, clip, track.color));\n  attachClipInteractions(el, track, clip, { trimL, trimR, fadeInH, fadeOutH });\n  el.addEventListener('contextmenu', (e) => { e.preventDefault(); selectClip(clip.id, false); showClipContextMenu(e.clientX, e.clientY, track, clip); });\n  return el;\n}\nfunction selectClip(id, additive){\n  if (!additive) state.selectedClipIds.clear();\n  if (id){\n    if (additive && state.selectedClipIds.has(id)) state.selectedClipIds.delete(id);\n    else state.selectedClipIds.add(id);\n  }\n  document.querySelectorAll('.clip').forEach(el => el.classList.toggle('selected', state.selectedClipIds.has(el.dataset.clip)));\n  const entry = getSelectedClipEntry();\n  if (entry) showInspector(entry.track, entry);\n}\nfunction renderAll(){\n  renderRuler();\n  renderTrackHeaders();\n  renderClips();\n  updateTimeDisplay();\n  const scroller = document.getElementById('timelineScroll');\n  const headers = document.getElementById('trackHeaders');\n  if (scroller && headers) headers.scrollTop = scroller.scrollTop;\n}\n\n/* ---------------- clip interactions ---------------- */\nfunction refreshClipElement(el, clip){\n  el.style.left = (clip.start * state.pxPerSec) + 'px';\n  el.style.width = Math.max(14, clip.duration * state.pxPerSec) + 'px';\n  const shades = el.querySelectorAll('.fade-shade');\n  if (shades[0]) shades[0].style.width = Math.min(60, (clip.fadeIn / Math.max(0.01, clip.duration)) * 100) + '%';\n  if (shades[1]) shades[1].style.width = Math.min(60, (clip.fadeOut / Math.max(0.01, clip.duration)) * 100) + '%';\n}\nfunction attachClipInteractions(el, track, clip, handles){\n  el.addEventListener('mousedown', (e) => {\n    if (e.button !== 0) return;\n    if (e.target === handles.trimL || e.target === handles.trimR || e.target === handles.fadeInH || e.target === handles.fadeOutH) return;\n    e.stopPropagation();\n    selectClip(clip.id, e.metaKey || e.ctrlKey);\n    state.selectedTrackId = track.id;\n    const snapshot = snapshotTracks();\n    const startX = e.clientX, startY = e.clientY;\n    const moving = [];\n    const collect = state.selectedClipIds.has(clip.id) && state.selectedClipIds.size > 1;\n    state.tracks.forEach(t => t.clips.forEach(c => {\n      if (collect ? state.selectedClipIds.has(c.id) : c.id === clip.id) moving.push({ clip: c, track: t, origStart: c.start });\n    }));\n    const container = document.getElementById('tracksContainer');\n    const containerRect = container.getBoundingClientRect();\n    let moved = false;\n    const onMove = (ev) => {\n      let dSec = (ev.clientX - startX) / state.pxPerSec;\n      if (Math.abs(ev.clientX - startX) > 2 || Math.abs(ev.clientY - startY) > 2) moved = true;\n      if (!moved) return;\n      let newStart = moving[0].origStart + dSec;\n      if (state.snap && !ev.altKey) newStart = Math.round(newStart / SNAP_SEC) * SNAP_SEC;\n      dSec = newStart - moving[0].origStart;\n      moving.forEach(m => { m.clip.start = Math.max(0, m.origStart + dSec); });\n      // vertical move to another lane (single clip only)\n      if (moving.length === 1){\n        const laneIdx = Math.floor((ev.clientY - containerRect.top) / LANE_H);\n        const target = state.tracks[DSP.clamp(laneIdx, 0, state.tracks.length - 1)];\n        if (target && target.id !== moving[0].track.id){\n          const m = moving[0];\n          m.track.clips = m.track.clips.filter(c => c.id !== m.clip.id);\n          target.clips.push(m.clip); m.track = target;\n          state.selectedTrackId = target.id;\n        }\n      }\n      moving.forEach(m => {\n        const cel = container.querySelector('.clip[data-clip=\"' + m.clip.id + '\"]');\n        if (cel) cel.style.left = (m.clip.start * state.pxPerSec) + 'px';\n      });\n    };\n    const onUp = () => {\n      document.removeEventListener('mousemove', onMove);\n      document.removeEventListener('mouseup', onUp);\n      if (moved){ pushUndoWithSnapshot(snapshot); renderAll(); }\n    };\n    document.addEventListener('mousemove', onMove);\n    document.addEventListener('mouseup', onUp);\n  });\n\n  const trimDrag = (side) => (e) => {\n    if (e.button !== 0) return;\n    e.stopPropagation(); e.preventDefault();\n    selectClip(clip.id, false);\n    const snapshot = snapshotTracks();\n    const startX = e.clientX;\n    const orig = { start: clip.start, offset: clip.offset, duration: clip.duration };\n    let changed = false;\n    const onMove = (ev) => {\n      const dSec = (ev.clientX - startX) / state.pxPerSec;\n      if (side === 'left'){\n        const delta = DSP.clamp(dSec, -orig.offset, orig.duration - 0.1);\n        clip.start = Math.max(0, orig.start + delta);\n        clip.offset = orig.offset + (clip.start - orig.start);\n        clip.duration = orig.duration - (clip.start - orig.start);\n      } else {\n        clip.duration = DSP.clamp(orig.duration + dSec, 0.1, clip.sourceDuration - orig.offset);\n      }\n      clip.fadeIn = Math.min(clip.fadeIn, clip.duration * 0.9);\n      clip.fadeOut = Math.min(clip.fadeOut, clip.duration * 0.9);\n      changed = true;\n      refreshClipElement(el, clip);\n    };\n    const onUp = () => {\n      document.removeEventListener('mousemove', onMove);\n      document.removeEventListener('mouseup', onUp);\n      if (changed){ pushUndoWithSnapshot(snapshot); renderAll(); }\n    };\n    document.addEventListener('mousemove', onMove);\n    document.addEventListener('mouseup', onUp);\n  };\n  handles.trimL.addEventListener('mousedown', trimDrag('left'));\n  handles.trimR.addEventListener('mousedown', trimDrag('right'));\n\n  const fadeDrag = (which) => (e) => {\n    if (e.button !== 0) return;\n    e.stopPropagation(); e.preventDefault();\n    selectClip(clip.id, false);\n    const snapshot = snapshotTracks();\n    const startX = e.clientX;\n    const orig = which === 'in' ? clip.fadeIn : clip.fadeOut;\n    let changed = false;\n    const onMove = (ev) => {\n      const dSec = (ev.clientX - startX) / state.pxPerSec;\n      const v = DSP.clamp(orig + (which === 'in' ? dSec : -dSec), 0, clip.duration * 0.9);\n      if (which === 'in') clip.fadeIn = v; else clip.fadeOut = v;\n      changed = true;\n      refreshClipElement(el, clip);\n    };\n    const onUp = () => {\n      document.removeEventListener('mousemove', onMove);\n      document.removeEventListener('mouseup', onUp);\n      if (changed){ pushUndoWithSnapshot(snapshot); renderAll(); showInspector(track, { track, clip }); }\n    };\n    document.addEventListener('mousemove', onMove);\n    document.addEventListener('mouseup', onUp);\n  };\n  handles.fadeInH.addEventListener('mousedown', fadeDrag('in'));\n  handles.fadeOutH.addEventListener('mousedown', fadeDrag('out'));\n}\n\n/* ---------------- clip operations ---------------- */\nfunction splitClipAt(track, clip, atTime, opts){\n  if (atTime <= clip.start + 0.05 || atTime >= clip.start + clip.duration - 0.05) return false;\n  if (!opts || !opts.skipUndo) pushUndo();\n  const second = Object.assign({}, clip, {\n    id: uid(),\n    start: atTime,\n    offset: clip.offset + (atTime - clip.start),\n    duration: clip.start + clip.duration - atTime,\n    fadeIn: 0,\n  });\n  clip.duration = atTime - clip.start;\n  clip.fadeOut = 0;\n  track.clips.splice(track.clips.indexOf(clip) + 1, 0, second);\n  track.clips.sort((a, b) => a.start - b.start);\n  return true;\n}\nfunction duplicateClip(track, clip){\n  pushUndo();\n  const copy = Object.assign({}, clip, { id: uid(), start: Math.max(0, getCurrentTimelinePosition()) });\n  if (Math.abs(copy.start - clip.start) < 0.01) copy.start = clip.start + clip.duration;\n  track.clips.push(copy);\n  track.clips.sort((a, b) => a.start - b.start);\n  renderAll();\n  setStatus('クリップを複製しました (配置先: 再生ヘッド位置)。');\n  return copy;\n}\nfunction deleteSelectedClips(){\n  if (!state.selectedClipIds.size) return;\n  pushUndo();\n  state.tracks.forEach(t => { t.clips = t.clips.filter(c => !state.selectedClipIds.has(c.id)); });\n  state.selectedClipIds.clear();\n  renderAll();\n  setStatus('選択クリップを削除しました。');\n}\nfunction showClipContextMenu(x, y, track, clip){\n  const menu = document.getElementById('clipContextMenu');\n  const inSelection = state.selectedClipIds.has(clip.id);\n  const targets = inSelection && state.selectedClipIds.size > 1\n    ? state.tracks.flatMap(t => t.clips.filter(c => state.selectedClipIds.has(c.id)))\n    : [clip];\n  menu.innerHTML =\n    '<div class=\"context-menu-item\" data-act=\"splitHere\">ここで分割 (右クリック位置)</div>' +\n    '<div class=\"context-menu-item\" data-act=\"splitHead\">再生ヘッドで分割 (Cmd+T)</div>' +\n    '<div class=\"context-menu-item\" data-act=\"dup\">複製 (再生ヘッド位置へ)</div>' +\n    '<div class=\"context-menu-sep\"></div>' +\n    '<div class=\"context-menu-item\" data-act=\"fade05\">両端フェード 0.5秒' + (targets.length > 1 ? ' (選択すべて)' : '') + '</div>' +\n    '<div class=\"context-menu-item\" data-act=\"fade10\">両端フェード 1.0秒' + (targets.length > 1 ? ' (選択すべて)' : '') + '</div>' +\n    '<div class=\"context-menu-item\" data-act=\"fade0\">フェード解除</div>' +\n    '<div class=\"context-menu-sep\"></div>' +\n    '<div class=\"context-menu-item danger\" data-act=\"del\">削除 (Delete)</div>';\n  menu.classList.remove('hidden');\n  menu.style.left = Math.min(window.innerWidth - 240, x) + 'px';\n  menu.style.top = Math.min(window.innerHeight - 300, y) + 'px';\n  const clickX = x;\n  menu.querySelectorAll('.context-menu-item').forEach(item => {\n    item.addEventListener('click', () => {\n      menu.classList.add('hidden');\n      const act = item.dataset.act;\n      if (act === 'splitHere'){\n        const lane = document.querySelector('.track-lane[data-track=\"' + track.id + '\"]');\n        const t = lane ? (clickX - lane.getBoundingClientRect().left) / state.pxPerSec : getCurrentTimelinePosition();\n        if (splitClipAt(track, clip, t)) { renderAll(); setStatus('クリップを分割しました。'); }\n      }\n      if (act === 'splitHead'){\n        if (splitClipAt(track, clip, getCurrentTimelinePosition())) { renderAll(); setStatus('再生ヘッドで分割しました。'); }\n        else setStatus('再生ヘッドがクリップの範囲内にありません。');\n      }\n      if (act === 'dup') duplicateClip(track, clip);\n      if (act === 'fade05'){ pushUndo(); targets.forEach(c => { c.fadeIn = Math.min(0.5, c.duration * 0.9); c.fadeOut = Math.min(0.5, c.duration * 0.9); }); renderAll(); }\n      if (act === 'fade10'){ pushUndo(); targets.forEach(c => { c.fadeIn = Math.min(1.0, c.duration * 0.9); c.fadeOut = Math.min(1.0, c.duration * 0.9); }); renderAll(); }\n      if (act === 'fade0'){ pushUndo(); targets.forEach(c => { c.fadeIn = 0; c.fadeOut = 0; }); renderAll(); }\n      if (act === 'del') deleteSelectedClips();\n    });\n  });\n}\ndocument.addEventListener('click', (e) => {\n  const menu = document.getElementById('clipContextMenu');\n  if (menu && !menu.contains(e.target)) menu.classList.add('hidden');\n});\n\n/* ---------------- import ---------------- */\nasync function decodeFile(file){\n  const ab = await file.arrayBuffer();\n  const buffer = await getAudioCtx().decodeAudioData(ab.slice(0));\n  let sourceId = file.name;\n  let n = 2;\n  while (buffersById.has(sourceId)) sourceId = file.name.replace(/(\\.[^/.]+)?$/, '#' + (n++) + '$1');\n  buffersById.set(sourceId, { buffer, fileName: file.name });\n  return { sourceId, buffer };\n}\nasync function addFilesToTimeline(files){\n  const audioFiles = [...files].filter(f => /audio|\\.(mp3|wav|m4a|aac|ogg|flac|aif|aiff)$/i.test(f.type + ' ' + f.name));\n  if (!audioFiles.length) return;\n  let appendAt = getTotalDuration();\n  pushUndo();\n  for (const file of audioFiles){\n    try {\n      setStatus(file.name + ' を解析中…');\n      const { sourceId, buffer } = await decodeFile(file);\n      const track = createTrack(file.name.replace(/\\.[^/.]+$/, ''));\n      const clip = {\n        id: uid(), sourceId, playSourceId: sourceId, fileName: file.name,\n        start: appendAt, offset: 0, duration: buffer.duration, sourceDuration: buffer.duration,\n        fadeIn: 0, fadeOut: 0, detectedBpm: null, bpmConfidence: 0, targetBpm: null,\n      };\n      track.clips.push(clip);\n      state.tracks.push(track);\n      appendAt += buffer.duration;\n      renderAll();\n      // BPM detection runs after the clip is visible; it never blocks import.\n      const chans = [];\n      for (let c = 0; c < buffer.numberOfChannels; c++) chans.push(buffer.getChannelData(c));\n      setTimeout(() => {\n        const res = DSP.detectBpmFromChannels(chans, buffer.sampleRate);\n        if (res && res.bpm){ clip.detectedBpm = res.bpm; clip.targetBpm = res.bpm; clip.bpmConfidence = res.confidence; renderAll(); }\n      }, 30);\n    } catch (err){\n      console.error(err);\n      setStatus('⚠ ' + file.name + ' を読み込めませんでした: ' + err.message);\n    }\n  }\n  setStatus(audioFiles.length + '曲を追加しました。曲同士を重ねて上の●でフェードを伸ばすか、「自動でつなぐ」で一括クロスフェードできます。');\n}\nfunction addEmptyTrack(){\n  pushUndo();\n  state.tracks.push(createTrack('トラック ' + (state.tracks.length + 1)));\n  renderAll();\n}\n\n/* ---------------- auto crossfade ---------------- */\nfunction autoCrossfade(){\n  const entries = [];\n  state.tracks.forEach(t => t.clips.forEach(c => entries.push({ track: t, clip: c })));\n  if (entries.length < 2) return setStatus('クロスフェードには2つ以上のクリップが必要です。');\n  const x = DSP.clamp(parseFloat(document.getElementById('xfadeSec').value) || 2, 0.1, 60);\n  entries.sort((a, b) => a.clip.start - b.clip.start);\n  pushUndo();\n  for (let i = 1; i < entries.length; i++){\n    const prev = entries[i - 1].clip, cur = entries[i].clip;\n    const overlap = Math.min(x, prev.duration * 0.45, cur.duration * 0.45);\n    cur.start = Math.max(0, prev.start + prev.duration - overlap);\n    prev.fadeOut = overlap;\n    cur.fadeIn = overlap;\n  }\n  renderAll();\n  setStatus('全' + entries.length + 'クリップを ' + x + '秒の等パワークロスフェードでつなぎました。各クリップのフェードは上の●ハンドルで微調整できます。');\n}\n\n/* ---------------- BPM stretch ---------------- */\nasync function applyBpmStretch(clip, targetBpm){\n  if (!clip.detectedBpm){\n    alert('元BPMが未確定です。インスペクターの「元BPM」欄に数値を入れてから適用してください。');\n    return;\n  }\n  targetBpm = DSP.clamp(targetBpm, 40, 300);\n  const ratio = clip.detectedBpm / targetBpm;\n  const changePct = Math.abs(1 - targetBpm / clip.detectedBpm) * 100;\n  const cacheKey = Math.abs(ratio - 1) < 0.002 ? clip.sourceId : clip.sourceId + '__bpm' + targetBpm.toFixed(2);\n  if (!buffersById.has(cacheKey)){\n    if (changePct >= 15 && !confirm(Math.round(changePct) + '%のテンポ変更です。タイムストレッチは変化幅が大きいほど音質劣化（こもり・ワブリング）が目立ちます。続行しますか？')) return;\n    const original = buffersById.get(clip.sourceId);\n    if (!original) return;\n    setStatus('BPM変更処理中 (' + clip.fileName + ': ' + clip.detectedBpm + '→' + targetBpm + ')… 長い曲では1分ほどかかります。');\n    setBusy(0);\n    try {\n      const chans = [];\n      for (let c = 0; c < original.buffer.numberOfChannels; c++) chans.push(original.buffer.getChannelData(c));\n      const stretched = await DSP.timeStretchChannels(chans, ratio, p => setBusy(p));\n      const ctx = getAudioCtx();\n      const outBuf = ctx.createBuffer(stretched.length, stretched[0].length, original.buffer.sampleRate);\n      stretched.forEach((data, c) => outBuf.copyToChannel(data, c));\n      buffersById.set(cacheKey, { buffer: outBuf, fileName: clip.fileName });\n      peaksCache.delete(cacheKey);\n    } finally { setBusy(null); }\n  }\n  pushUndo();\n  clip.playSourceId = cacheKey;\n  clip.targetBpm = targetBpm;\n  const newBuf = buffersById.get(cacheKey).buffer;\n  clip.sourceDuration = newBuf.duration;\n  clip.offset = 0;\n  clip.duration = newBuf.duration;\n  renderAll();\n  const entry = getSelectedClipEntry();\n  if (entry) showInspector(entry.track, entry);\n  setStatus('BPM変更完了: ' + clip.fileName + ' → ' + targetBpm + ' BPM (ピッチはそのまま)');\n}\n\n/* ---------------- inspector ---------------- */\nfunction fxRow(label, inner){ return '<div class=\"fx-row\"><span>' + label + '</span>' + inner + '</div>'; }\nfunction showInspector(track, clipEntry){\n  const body = document.getElementById('inspBody');\n  const target = document.getElementById('inspTarget');\n  if (!track){ body.innerHTML = '<p class=\"insp-note\">トラックの FX ボタンか、クリップを選ぶとここに出ます。</p>'; target.textContent = ''; return; }\n  state.selectedTrackId = track.id;\n  const fx = normalizeEffects(track.effects);\n  track.effects = fx;\n  target.textContent = '— ' + track.name + (clipEntry ? ' / ' + (clipEntry.clip.fileName || '') : '');\n  const refBpm = (track.clips.find(c => c.detectedBpm) || {}).detectedBpm || null;\n  const delaySyncBtns = refBpm ? [4, 8, 16].map(div =>\n    '<button type=\"button\" class=\"preset-btn\" data-div=\"' + div + '\">' + (div === 4 ? '1/4' : div === 8 ? '1/8' : '1/16') + '</button>').join('') +\n    '<span class=\"insp-note\">♩' + refBpm + '基準</span>' : '<span class=\"insp-note\">BPM未検出のため同期プリセット不可</span>';\n\n  let html = '';\n  html += '<div class=\"insp-section\"><h4>EQ (直列・3バンド)</h4>' +\n    fxRow('低音 120Hz', '<input type=\"range\" id=\"eqLow\" min=\"-15\" max=\"15\" step=\"0.5\" value=\"' + fx.eq.low + '\"><span class=\"fx-val\" id=\"eqLowVal\">' + fx.eq.low.toFixed(1) + ' dB</span>') +\n    fxRow('中音 1kHz', '<input type=\"range\" id=\"eqMid\" min=\"-15\" max=\"15\" step=\"0.5\" value=\"' + fx.eq.mid + '\"><span class=\"fx-val\" id=\"eqMidVal\">' + fx.eq.mid.toFixed(1) + ' dB</span>') +\n    fxRow('高音 6.5kHz', '<input type=\"range\" id=\"eqHigh\" min=\"-15\" max=\"15\" step=\"0.5\" value=\"' + fx.eq.high + '\"><span class=\"fx-val\" id=\"eqHighVal\">' + fx.eq.high.toFixed(1) + ' dB</span>') +\n    '<p class=\"insp-note\">0 dB = 素通り。こもる曲は低音を少し下げ、高音を少し上げると抜けます。</p></div>';\n\n  html += '<div class=\"insp-section\"><h4><label><input type=\"checkbox\" id=\"fltOn\" ' + (fx.filter.enabled ? 'checked' : '') + '> フィルター (直列)</label></h4>' +\n    fxRow('種類', '<select id=\"fltType\"><option value=\"lowpass\" ' + (fx.filter.type === 'lowpass' ? 'selected' : '') + '>ローパス</option><option value=\"highpass\" ' + (fx.filter.type === 'highpass' ? 'selected' : '') + '>ハイパス</option></select>') +\n    fxRow('カットオフ', '<input type=\"range\" id=\"fltFreq\" min=\"0\" max=\"1000\" step=\"1\" value=\"' + Math.round(Math.log(fx.filter.freq / 100) / Math.log(180) * 1000) + '\"><span class=\"fx-val\" id=\"fltFreqVal\">' + Math.round(fx.filter.freq) + ' Hz</span>') +\n    '<p class=\"insp-note\">v16では直列接続に変更。旧版の並列ミックスは位相干渉で音が痩せていました。</p></div>';\n\n  html += '<div class=\"insp-section\"><h4><label><input type=\"checkbox\" id=\"dlyOn\" ' + (fx.delay.enabled ? 'checked' : '') + '> ディレイ (減衰付き)</label></h4>' +\n    fxRow('同期', delaySyncBtns) +\n    fxRow('タイム', '<input type=\"range\" id=\"dlyTime\" min=\"0.03\" max=\"2.5\" step=\"0.01\" value=\"' + fx.delay.timeSec + '\"><span class=\"fx-val\" id=\"dlyTimeVal\">' + fx.delay.timeSec.toFixed(2) + ' s</span>') +\n    fxRow('フィードバック', '<input type=\"range\" id=\"dlyFb\" min=\"0\" max=\"0.85\" step=\"0.01\" value=\"' + fx.delay.feedback + '\"><span class=\"fx-val\" id=\"dlyFbVal\">' + Math.round(fx.delay.feedback * 100) + ' %</span>') +\n    fxRow('ミックス', '<input type=\"range\" id=\"dlyMix\" min=\"0\" max=\"0.9\" step=\"0.01\" value=\"' + fx.delay.mix + '\"><span class=\"fx-val\" id=\"dlyMixVal\">' + Math.round(fx.delay.mix * 100) + ' %</span>') +\n    '<p class=\"insp-note\">繰り返し音はローパスで暗くなりながら消えます (アナログエコー方式)。</p></div>';\n\n  html += '<div class=\"insp-section\"><h4><label><input type=\"checkbox\" id=\"revOn\" ' + (fx.reverb.enabled ? 'checked' : '') + '> リバーブ (センド)</label></h4>' +\n    fxRow('ミックス', '<input type=\"range\" id=\"revMix\" min=\"0\" max=\"0.9\" step=\"0.01\" value=\"' + fx.reverb.mix + '\"><span class=\"fx-val\" id=\"revMixVal\">' + Math.round(fx.reverb.mix * 100) + ' %</span>') +\n    fxRow('空間サイズ', '<input type=\"range\" id=\"revSize\" min=\"0.4\" max=\"5\" step=\"0.1\" value=\"' + fx.reverb.size + '\"><span class=\"fx-val\" id=\"revSizeVal\">' + fx.reverb.size.toFixed(1) + ' s</span>') +\n    '<p class=\"insp-note\">残響は高域から減衰するIRに作り替え済み。原音はリバーブを通りません。</p></div>';\n\n  if (clipEntry){\n    const clip = clipEntry.clip;\n    html += '<div class=\"insp-section\"><h4>クリップ — ' + escapeHtml(clip.fileName || '') + '</h4>' +\n      fxRow('開始 (秒)', '<input type=\"number\" id=\"clipStart\" min=\"0\" step=\"0.1\" value=\"' + clip.start.toFixed(2) + '\">') +\n      fxRow('フェードイン', '<input type=\"range\" id=\"clipFadeIn\" min=\"0\" max=\"' + Math.max(0.1, clip.duration * 0.9) + '\" step=\"0.05\" value=\"' + clip.fadeIn + '\"><span class=\"fx-val\" id=\"clipFadeInVal\">' + clip.fadeIn.toFixed(2) + ' s</span>') +\n      fxRow('フェードアウト', '<input type=\"range\" id=\"clipFadeOut\" min=\"0\" max=\"' + Math.max(0.1, clip.duration * 0.9) + '\" step=\"0.05\" value=\"' + clip.fadeOut + '\"><span class=\"fx-val\" id=\"clipFadeOutVal\">' + clip.fadeOut.toFixed(2) + ' s</span>') +\n      fxRow('元BPM', '<input type=\"number\" id=\"clipOrigBpm\" min=\"40\" max=\"300\" step=\"1\" value=\"' + (clip.detectedBpm || '') + '\" placeholder=\"未検出\">') +\n      fxRow('目標BPM', '<input type=\"number\" id=\"clipTargetBpm\" min=\"40\" max=\"300\" step=\"1\" value=\"' + (clip.targetBpm || clip.detectedBpm || '') + '\"> <button type=\"button\" class=\"preset-btn\" id=\"clipApplyBpm\">適用</button> <button type=\"button\" class=\"preset-btn\" id=\"clipResetBpm\">元に戻す</button>') +\n      fxRow('操作', '<button type=\"button\" class=\"preset-btn\" id=\"clipSplit\">再生ヘッドで分割</button> <button type=\"button\" class=\"preset-btn\" id=\"clipDup\">複製</button> <button type=\"button\" class=\"preset-btn\" id=\"clipDel\">削除</button>') +\n      '<p class=\"insp-note\">フェードは等パワー曲線です。0秒でも端には6msのクリック防止フェードが入ります。</p></div>';\n  }\n  body.innerHTML = html;\n\n  const bind = (id, valId, fmt, apply) => {\n    const el = document.getElementById(id);\n    if (!el) return;\n    el.addEventListener('input', () => {\n      const v = parseFloat(el.value);\n      apply(v);\n      if (valId) document.getElementById(valId).textContent = fmt(v);\n      applyTrackParamsLive(track);\n    });\n  };\n  bind('eqLow', 'eqLowVal', v => v.toFixed(1) + ' dB', v => { fx.eq.low = v; });\n  bind('eqMid', 'eqMidVal', v => v.toFixed(1) + ' dB', v => { fx.eq.mid = v; });\n  bind('eqHigh', 'eqHighVal', v => v.toFixed(1) + ' dB', v => { fx.eq.high = v; });\n  const fltOn = document.getElementById('fltOn');\n  if (fltOn) fltOn.addEventListener('change', () => { fx.filter.enabled = fltOn.checked; applyTrackParamsLive(track); });\n  const fltType = document.getElementById('fltType');\n  if (fltType) fltType.addEventListener('change', () => { fx.filter.type = fltType.value; applyTrackParamsLive(track); });\n  bind('fltFreq', 'fltFreqVal', v => Math.round(100 * Math.pow(180, v / 1000)) + ' Hz', v => { fx.filter.freq = 100 * Math.pow(180, v / 1000); });\n  const dlyOn = document.getElementById('dlyOn');\n  if (dlyOn) dlyOn.addEventListener('change', () => { fx.delay.enabled = dlyOn.checked; applyTrackParamsLive(track); });\n  bind('dlyTime', 'dlyTimeVal', v => v.toFixed(2) + ' s', v => { fx.delay.timeSec = v; });\n  bind('dlyFb', 'dlyFbVal', v => Math.round(v * 100) + ' %', v => { fx.delay.feedback = v; });\n  bind('dlyMix', 'dlyMixVal', v => Math.round(v * 100) + ' %', v => { fx.delay.mix = v; });\n  body.querySelectorAll('[data-div]').forEach(btn => btn.addEventListener('click', () => {\n    if (!refBpm) return;\n    const sec = DSP.clamp((60 / refBpm) * (4 / parseInt(btn.dataset.div, 10)), 0.03, 2.5);\n    fx.delay.timeSec = Math.round(sec * 100) / 100;\n    fx.delay.enabled = true;\n    showInspector(track, clipEntry);\n    applyTrackParamsLive(track);\n  }));\n  const revOn = document.getElementById('revOn');\n  if (revOn) revOn.addEventListener('change', () => { fx.reverb.enabled = revOn.checked; applyTrackParamsLive(track); });\n  bind('revMix', 'revMixVal', v => Math.round(v * 100) + ' %', v => { fx.reverb.mix = v; });\n  bind('revSize', 'revSizeVal', v => v.toFixed(1) + ' s', v => { fx.reverb.size = v; });\n\n  if (clipEntry){\n    const clip = clipEntry.clip;\n    const startEl = document.getElementById('clipStart');\n    startEl.addEventListener('change', () => { pushUndo(); clip.start = Math.max(0, parseFloat(startEl.value) || 0); renderAll(); showInspector(track, { track, clip }); });\n    const bindFade = (id, valId, key) => {\n      const el = document.getElementById(id);\n      el.addEventListener('input', () => {\n        clip[key] = parseFloat(el.value);\n        document.getElementById(valId).textContent = clip[key].toFixed(2) + ' s';\n        const cel = document.querySelector('.clip[data-clip=\"' + clip.id + '\"]');\n        if (cel) refreshClipElement(cel, clip);\n      });\n      el.addEventListener('change', () => renderAll());\n    };\n    bindFade('clipFadeIn', 'clipFadeInVal', 'fadeIn');\n    bindFade('clipFadeOut', 'clipFadeOutVal', 'fadeOut');\n    document.getElementById('clipApplyBpm').addEventListener('click', async () => {\n      const orig = parseFloat(document.getElementById('clipOrigBpm').value);\n      if (orig) clip.detectedBpm = orig;\n      const target = parseFloat(document.getElementById('clipTargetBpm').value);\n      if (target) await applyBpmStretch(clip, target);\n    });\n    document.getElementById('clipResetBpm').addEventListener('click', async () => {\n      if (clip.detectedBpm) await applyBpmStretch(clip, clip.detectedBpm);\n    });\n    document.getElementById('clipSplit').addEventListener('click', () => {\n      if (splitClipAt(track, clip, getCurrentTimelinePosition())){ renderAll(); setStatus('再生ヘッドで分割しました。'); }\n      else setStatus('再生ヘッドがクリップの範囲内にありません。');\n    });\n    document.getElementById('clipDup').addEventListener('click', () => duplicateClip(track, clip));\n    document.getElementById('clipDel').addEventListener('click', () => deleteSelectedClips());\n  }\n}\n\n/* ---------------- project save / load ---------------- */\nfunction saveProject(){\n  const project = {\n    app: 'BGM MIX STUDIO', version: 16, pxPerSec: state.pxPerSec, masterPreset: state.masterPreset,\n    tracks: state.tracks.map(t => ({\n      name: t.name, color: t.color, volume: t.volume, pan: t.pan, muted: t.muted, solo: t.solo,\n      effects: normalizeEffects(t.effects),\n      clips: t.clips.map(c => ({\n        fileName: c.fileName, start: c.start, offset: c.offset, duration: c.duration,\n        sourceDuration: c.sourceDuration, fadeIn: c.fadeIn, fadeOut: c.fadeOut,\n        detectedBpm: c.detectedBpm, targetBpm: c.targetBpm,\n      })),\n    })),\n  };\n  const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json' });\n  downloadBlob(blob, 'bgm_mix_project.bgmmix.json');\n  setStatus('プロジェクトを保存しました。音源ファイル自体は含まれません (再読込時に同名ファイルの再選択が必要です)。');\n}\nlet pendingProject = null;\nasync function loadProjectJson(file){\n  try {\n    const project = JSON.parse(await file.text());\n    if (!project || !Array.isArray(project.tracks)) throw new Error('BGM MIX STUDIOのプロジェクトではありません');\n    pendingProject = project;\n    setStatus('プロジェクトを読みました。次に、プロジェクトで使っている音源ファイルをすべて選択してください。');\n    document.getElementById('relinkInput').click();\n  } catch (err){ setStatus('⚠ プロジェクトを読めませんでした: ' + err.message); }\n}\nasync function relinkProject(files){\n  if (!pendingProject) return;\n  const byName = new Map();\n  for (const f of files){\n    try { const { sourceId } = await decodeFile(f); byName.set(f.name, sourceId); } catch (e){ console.warn(e); }\n  }\n  stopPlayback();\n  disposeLiveTrackNodes();\n  const missing = [];\n  state.tracks = pendingProject.tracks.map(saved => {\n    const track = createTrack(saved.name);\n    Object.assign(track, { color: saved.color || track.color, volume: saved.volume, pan: saved.pan, muted: !!saved.muted, solo: !!saved.solo, effects: normalizeEffects(saved.effects) });\n    track.clips = (saved.clips || []).flatMap(c => {\n      const sourceId = byName.get(c.fileName);\n      if (!sourceId){ missing.push(c.fileName); return []; }\n      return [Object.assign({}, c, { id: uid(), sourceId, playSourceId: sourceId })];\n    });\n    return track;\n  });\n  if (pendingProject.masterPreset){ state.masterPreset = pendingProject.masterPreset; document.getElementById('masterPreset').value = state.masterPreset; }\n  if (pendingProject.pxPerSec) state.pxPerSec = pendingProject.pxPerSec;\n  pendingProject = null;\n  undoStack.length = 0; redoStack.length = 0;\n  renderAll();\n  setStatus(missing.length\n    ? 'プロジェクトを開きました。見つからなかった音源: ' + [...new Set(missing)].join(', ') + ' (そのクリップは読み込まれていません)。BPM変更済みクリップは元の音源で読み込まれるので、必要なら再適用してください。'\n    : 'プロジェクトを開きました。');\n}\n\n/* ---------------- init ---------------- */\nfunction initEvents(){\n  const $ = id => document.getElementById(id);\n  $('btnImport').addEventListener('click', () => $('fileInput').click());\n  $('fileInput').addEventListener('change', (e) => { addFilesToTimeline(e.target.files); e.target.value = ''; });\n  $('btnAddEmptyTrack').addEventListener('click', addEmptyTrack);\n  $('btnPlay').addEventListener('click', togglePlay);\n  $('btnStop').addEventListener('click', stopPlayback);\n  $('btnRewind').addEventListener('click', () => seekTo(0));\n  $('btnExport').addEventListener('click', handleExport);\n  $('btnExportSplit').addEventListener('click', handleExportSplit);\n  $('btnAutoXfade').addEventListener('click', autoCrossfade);\n  $('btnSaveProject').addEventListener('click', saveProject);\n  $('btnLoadProject').addEventListener('click', () => $('projectInput').click());\n  $('projectInput').addEventListener('change', (e) => { if (e.target.files[0]) loadProjectJson(e.target.files[0]); e.target.value = ''; });\n  $('relinkInput').addEventListener('change', (e) => { relinkProject(e.target.files); e.target.value = ''; });\n  $('chkSnap').addEventListener('change', (e) => { state.snap = e.target.checked; });\n  $('meterClip').addEventListener('click', () => { lastClipAt = 0; $('meterClip').classList.remove('active'); });\n  $('masterPreset').addEventListener('change', (e) => {\n    state.masterPreset = e.target.value;\n    rebuildLiveMaster();\n    setStatus('マスタープリセット: ' + (state.masterPreset === 'clean' ? 'Clean (リミッターのみ)' : state.masterPreset === 'glue' ? 'Glue (軽いグルーコンプ + リミッター)' : 'Studio (グルー + 軽いサチュレーション + リミッター)'));\n  });\n  $('inspClose').addEventListener('click', () => showInspector(null, null));\n  $('zoomIn').addEventListener('click', () => { state.pxPerSec = Math.min(400, state.pxPerSec * 1.25); renderAll(); });\n  $('zoomOut').addEventListener('click', () => { state.pxPerSec = Math.max(3, state.pxPerSec / 1.25); renderAll(); });\n  $('ruler').addEventListener('mousedown', (e) => {\n    const rect = $('tracksContainer').getBoundingClientRect();\n    seekTo(Math.max(0, (e.clientX - rect.left) / state.pxPerSec));\n  });\n\n  document.addEventListener('keydown', (e) => {\n    const tag = e.target.tagName;\n    if (tag === 'INPUT' || tag === 'SELECT' || tag === 'TEXTAREA') return;\n    if (e.code === 'Space'){ e.preventDefault(); togglePlay(); }\n    else if (e.key === 'Home'){ e.preventDefault(); seekTo(0); }\n    else if (e.key === 'Delete' || e.key === 'Backspace'){ deleteSelectedClips(); }\n    else if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'z' && !e.shiftKey){ e.preventDefault(); undo(); }\n    else if ((e.metaKey || e.ctrlKey) && (e.key.toLowerCase() === 'y' || (e.shiftKey && e.key.toLowerCase() === 'z'))){ e.preventDefault(); redo(); }\n    else if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 't'){\n      e.preventDefault();\n      const entry = getSelectedClipEntry();\n      if (entry && splitClipAt(entry.track, entry.clip, getCurrentTimelinePosition())){ renderAll(); setStatus('再生ヘッドで分割しました。'); }\n      else setStatus('分割できるクリップが選ばれていないか、再生ヘッドが範囲外です。');\n    }\n    else if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'd'){\n      e.preventDefault();\n      const entry = getSelectedClipEntry();\n      if (entry) duplicateClip(entry.track, entry.clip);\n    }\n  });\n\n  const scroller = $('timelineScroll'), headers = $('trackHeaders');\n  scroller.addEventListener('scroll', () => { headers.scrollTop = scroller.scrollTop; });\n  headers.addEventListener('wheel', (e) => { scroller.scrollTop += e.deltaY; e.preventDefault(); }, { passive: false });\n  scroller.addEventListener('wheel', (e) => {\n    if (!e.ctrlKey) return;\n    e.preventDefault();\n    const rect = scroller.getBoundingClientRect();\n    const cursorX = e.clientX - rect.left + scroller.scrollLeft;\n    const timeAtCursor = cursorX / state.pxPerSec;\n    state.pxPerSec = DSP.clamp(state.pxPerSec * Math.exp(-e.deltaY * 0.012), 3, 400);\n    renderAll();\n    requestAnimationFrame(() => { scroller.scrollLeft = timeAtCursor * state.pxPerSec - (e.clientX - rect.left); });\n  }, { passive: false });\n\n  // drag & drop import (+ project json)\n  const overlay = $('dropOverlay');\n  window.addEventListener('dragenter', (e) => { e.preventDefault(); overlay.classList.remove('hidden'); });\n  window.addEventListener('dragover', (e) => e.preventDefault());\n  window.addEventListener('dragleave', (e) => { if (e.relatedTarget === null) overlay.classList.add('hidden'); });\n  window.addEventListener('drop', (e) => {\n    e.preventDefault();\n    overlay.classList.add('hidden');\n    const files = [...(e.dataTransfer ? e.dataTransfer.files : [])];\n    const json = files.find(f => /\\.json$/i.test(f.name));\n    if (json && files.length === 1) loadProjectJson(json);\n    else addFilesToTimeline(files);\n  });\n\n  document.addEventListener('click', (e) => {\n    if (!e.target.closest('.clip') && !e.target.closest('#inspector') && !e.target.closest('.track-header') && !e.target.closest('.context-menu')){\n      state.selectedClipIds.clear();\n      document.querySelectorAll('.clip.selected').forEach(el => el.classList.remove('selected'));\n    }\n  });\n  setInterval(() => { if (!state.isPlaying) updateTimeDisplay(); }, 500);\n}\n\nif (typeof window !== 'undefined'){\n  window.__APP__ = { buildMasterChain, buildTrackChain, scheduleEnvelope, state, normalizeEffects, createDefaultEffects };\n}\nif (typeof document !== 'undefined' && document.getElementById && document.getElementById('btnPlay')){\n  initEvents();\n  renderAll();\n}\n</script>\n</body>\n</html>\n"
